fn bump(counts: Map<Str, Int>, w: Str) -> Map<Str, Int> {
  let mut m = counts;
  let n = m.get(w).unwrap_or(0);
  m.insert(w, n + 1);
  m
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let data = input.read("text.txt")?;
  let mut counts: Map<Str, Int> = Map::new();
  let mut cur = "".to_bytes();
  for b in data {
    let mut c = b;
    if c >= 65 && c <= 90 {
      c = c + 32;
    }
    if c >= 97 && c <= 122 {
      cur.push(c);
    } else {
      if cur.len() > 0 {
        counts = bump(counts, cur.to_str());
        cur = "".to_bytes();
      }
    }
  }
  if cur.len() > 0 {
    counts = bump(counts, cur.to_str());
  }
  let mut words = counts.keys();
  let snapshot = counts;
  words.sort_by(|a, b| snapshot.get(a).unwrap_or(0) > snapshot.get(b).unwrap_or(0));
  let n = words.len().min(5);
  let mut lines: List<Str> = [];
  for i in 0..n {
    let w = words[i];
    lines.push(w + " " + snapshot.get(w).unwrap_or(0).to_str());
  }
  Ok(lines.join("\n"))
}

struct Tot { region: Str, qty: Int, rev: Int }

fn money(c: Int) -> Str {
  let neg = c < 0;
  let a = if neg { 0 - c } else { c };
  let r = a % 100;
  let rs = if r < 10 { "0" + r.to_str() } else { r.to_str() };
  let sign = if neg { "-" } else { "" };
  sign + (a / 100).to_str() + "." + rs
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("sales.csv")?.to_str();
  let lines = text.lines();
  let mut tot: Map<Str, Tot> = Map::new();
  let mut skipped = 0;
  let mut i = 1;
  while i < lines.len() {
    let line = lines[i];
    i += 1;
    if line.trim() == "" { continue; }
    let parts = line.split(",");
    if parts.len() != 5 { skipped += 1; continue; }
    let Some(q) = parts[3].trim().parse_int() else { skipped += 1; continue; };
    let Some(u) = parts[4].trim().parse_int() else { skipped += 1; continue; };
    let region = parts[1].trim();
    let cur = tot.get(region).unwrap_or(Tot { region: region, qty: 0, rev: 0 });
    tot.insert(region, Tot { qty: cur.qty + q, rev: cur.rev + q * u, ..cur });
  }
  let mut all: List<Tot> = [];
  for k in tot.keys() {
    let Some(t) = tot.get(k) else { continue; };
    all.push(t);
  }
  all.sort_by(|a, b| a.rev > b.rev || (a.rev == b.rev && a.region < b.region));
  let mut out: List<Str> = [];
  for t in all {
    out.push(t.region + " " + t.qty.to_str() + " " + money(t.rev));
  }
  out.push("skipped " + skipped.to_str());
  Ok(out.join("\n"))
}

struct Entry { ip: Str, status: Int, size: Int, path: Str }
struct ErrRow { ip: Str, count: Int }

fn parse_line(line: Str) -> Option<Entry> {
  let parts = line.split("\"");
  if parts.len() != 3 { return None; }
  let prefix = parts[0];
  if !prefix.contains("[") { return None; }
  let ip = prefix.split(" ")[0];
  if ip.len() == 0 { return None; }
  let words = parts[1].split(" ");
  if words.len() < 2 { return None; }
  let p = words[1];
  let path = match p.find("?") {
    Some(i) => p.slice(0, i),
    None => p,
  };
  let rest = parts[2].trim().split(" ");
  if rest.len() != 2 { return None; }
  let status = rest[0].parse_int()?;
  let size = if rest[1] == "-" { 0 } else { rest[1].parse_int()? };
  Some(Entry { ip: ip, status: status, size: size, path: path })
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("access.log")?.to_str();
  let mut statuses: Map<Int, Int> = Map::new();
  let mut paths: Map<Str, Int> = Map::new();
  let mut errs: Map<Str, Int> = Map::new();
  let mut total = 0;
  for raw in text.lines() {
    let Some(e) = parse_line(raw.trim()) else { continue; };
    let c = statuses.get(e.status).unwrap_or(0);
    statuses.insert(e.status, c + 1);
    total = total + e.size;
    let pc = paths.get(e.path).unwrap_or(0);
    paths.insert(e.path, pc + 1);
    if e.status >= 500 && e.status <= 599 {
      let ec = errs.get(e.ip).unwrap_or(0);
      errs.insert(e.ip, ec + 1);
    }
  }
  let mut lines: List<Str> = [];
  for s in statuses.keys() {
    lines.push(s.to_str() + " " + statuses.get(s).unwrap_or(0).to_str());
  }
  lines.push("bytes " + total.to_str());
  let mut best = "";
  let mut best_n = 0;
  for p in paths.keys() {
    let n = paths.get(p).unwrap_or(0);
    if n > best_n {
      best_n = n;
      best = p;
    }
  }
  if best_n > 0 {
    lines.push("top " + best + " " + best_n.to_str());
  }
  let mut rows: List<ErrRow> = [];
  for ip in errs.keys() {
    rows.push(ErrRow { ip: ip, count: errs.get(ip).unwrap_or(0) });
  }
  rows.sort_by(|a, b| a.count > b.count || (a.count == b.count && a.ip < b.ip));
  for r in rows {
    lines.push("errors " + r.ip + " " + r.count.to_str());
  }
  Ok(lines.join("\n"))
}

fn order_total(o: Json) -> Int {
  let items = o.get("items").and_then(|j| j.as_list()).unwrap_or([]);
  let mut t = 0;
  for it in items {
    let q = it.get("qty").and_then(|j| j.as_int()).unwrap_or(0);
    let p = it.get("price_cents").and_then(|j| j.as_int()).unwrap_or(0);
    t = t + q * p;
  }
  t
}

fn main(input: Dir) -> Result<Str, Str> {
  let bytes = match input.read("orders.json") {
    Ok(b) => b,
    Err(_) => return Err("cannot read orders.json"),
  };
  let doc = match bytes.to_str().parse_json() {
    Ok(j) => j,
    Err(e) => return Err(e),
  };
  let orders = doc.as_list().unwrap_or([]);
  let mut counts: Map<Str, Int> = Map::new();
  let mut totals: Map<Str, Int> = Map::new();
  let mut ref_n = 0;
  let mut ref_total = 0;
  let mut pend_n = 0;
  for o in orders {
    let status = o.get("status").and_then(|j| j.as_str()).unwrap_or("");
    let t = order_total(o);
    if status == "paid" {
      let c = o.get("customer").and_then(|j| j.as_str()).unwrap_or("");
      counts.insert(c, counts.get(c).unwrap_or(0) + 1);
      totals.insert(c, totals.get(c).unwrap_or(0) + t);
    } else if status == "refunded" {
      ref_n = ref_n + 1;
      ref_total = ref_total + t;
    } else if status == "pending" {
      pend_n = pend_n + 1;
    }
  }
  let mut out = "";
  for c in counts.keys() {
    out = out + c + " " + counts.get(c).unwrap_or(0).to_str() + " " + totals.get(c).unwrap_or(0).to_str() + "\n";
  }
  out = out + "refunded " + ref_n.to_str() + " " + ref_total.to_str() + "\n";
  out = out + "pending " + pend_n.to_str() + "\n";
  Ok(out)
}

fn normalize(s: Str) -> Option<Str> {
  let parts = s.split("@");
  if parts.len() != 2 { return None; }
  let mut local = parts[0];
  let domain = parts[1];
  if local.len() == 0 { return None; }
  if !domain.contains(".") || domain.starts_with(".") || domain.ends_with(".") {
    return None;
  }
  if domain == "gmail.com" {
    if let Some(i) = local.find("+") {
      local = local.slice(0, i);
    }
    local = local.replace(".", "");
  }
  Some(local + "@" + domain)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("emails.txt")?.to_str();
  let mut seen: Map<Str, Bool> = Map::new();
  let mut invalid = 0;
  for line in text.lines() {
    let s = line.trim().to_lowercase();
    if s.len() == 0 { continue; }
    match normalize(s) {
      Some(a) => { seen.insert(a, true); }
      None => { invalid += 1; }
    }
  }
  let mut out = "";
  for k in seen.keys() {
    out = out + k + "\n";
  }
  out = out + "invalid " + invalid.to_str() + "\n";
  Ok(out)
}

fn roman(n: Int) -> Str {
  let vals: List<Int> = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
  let syms: List<Str> = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"];
  let mut r = "";
  let mut m = n;
  let mut i = 0;
  while i < 13 {
    while m >= vals[i] {
      r = r + syms[i];
      m -= vals[i];
    }
    i += 1;
  }
  r
}

fn val(c: Str) -> Int {
  match c {
    "I" => 1,
    "V" => 5,
    "X" => 10,
    "L" => 50,
    "C" => 100,
    "D" => 500,
    "M" => 1000,
    _ => 0,
  }
}

fn from_roman(s: Str) -> Option<Int> {
  let mut vs: List<Int> = [];
  for c in s.chars() {
    let v = val(c);
    if v == 0 { return None; }
    vs.push(v);
  }
  let n = vs.len();
  let mut total = 0;
  for i in 0..n {
    if i + 1 < n && vs[i] < vs[i + 1] {
      total -= vs[i];
    } else {
      total += vs[i];
    }
  }
  if total >= 1 && total <= 3999 && roman(total) == s {
    Some(total)
  } else {
    None
  }
}

fn is_digits(s: Str) -> Bool {
  if s.len() == 0 { return false; }
  for c in s.chars() {
    if !(c >= "0" && c <= "9") { return false; }
  }
  true
}

fn convert(t: Str) -> Str {
  if is_digits(t) {
    match t.parse_int() {
      Some(n) => {
        if n >= 1 && n <= 3999 { roman(n) } else { "invalid" }
      }
      None => "invalid",
    }
  } else {
    match from_roman(t) {
      Some(n) => n.to_str(),
      None => "invalid",
    }
  }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("numbers.txt")?.to_str();
  let mut out: List<Str> = [];
  for line in text.lines() {
    let t = line.trim();
    if t.len() == 0 { continue; }
    out.push(t + " = " + convert(t));
  }
  Ok(out.join("\n"))
}

fn check(line: Str) -> Str {
  let mut stack: List<Str> = [];
  let mut col = 0;
  for b in line.to_bytes() {
    col += 1;
    if b == 40 {
      stack.push(")");
    } else if b == 91 {
      stack.push("]");
    } else if b == 123 {
      stack.push("}");
    } else {
      let mut y = "";
      if b == 41 {
        y = ")";
      } else if b == 93 {
        y = "]";
      } else if b == 125 {
        y = "}";
      }
      if y != "" {
        let top = stack.pop();
        if top.is_none() {
          return "col " + col.to_str() + ": unexpected " + y;
        } else {
          let x = top.unwrap_or("");
          if x != y {
            return "col " + col.to_str() + ": expected " + x + ", found " + y;
          }
        }
      }
    }
  }
  let last = stack.pop();
  match last {
    Some(x) => "unclosed " + x,
    None => "ok",
  }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("snippets.txt")?.to_str();
  let mut res: List<Str> = [];
  for line in text.lines() {
    res.push(check(line));
  }
  Ok(res.join("\n"))
}

fn pct(t: List<Int>, p: Int) -> Int {
  let n = t.len();
  let idx = (p * n + 99) / 100;
  t[idx - 1]
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("timings.log")?.to_str();
  let mut m: Map<Str, List<Int>> = Map::new();
  for line in text.lines() {
    let parts = line.split(" ");
    if parts.len() != 3 { continue; }
    let Some(ms) = parts[2].parse_int() else { continue; };
    let key = parts[0] + " " + parts[1];
    let mut cur: List<Int> = match m.get(key) {
      Some(l) => l,
      None => [],
    };
    cur.push(ms);
    m.insert(key, cur);
  }
  let mut out = "";
  for k in m.keys() {
    let mut t: List<Int> = match m.get(k) {
      Some(l) => l,
      None => [],
    };
    if t.len() == 0 { continue; }
    t.sort();
    out = out + k + " count=" + t.len().to_str() + " p50=" + pct(t, 50).to_str()
      + " p95=" + pct(t, 95).to_str() + " max=" + t[t.len() - 1].to_str() + "\n";
  }
  Ok(out)
}

struct Edge { to: Str, w: Int }
struct Trip { from: Str, to: Str }

fn words(s: Str) -> List<Str> {
  let mut out: List<Str> = [];
  for p in s.replace("\t", " ").split(" ") {
    if p.len() > 0 { out.push(p); }
  }
  out
}

fn add_edge(adj: HashMap<Str, List<Edge>>, a: Str, b: Str, c: Int) -> HashMap<Str, List<Edge>> {
  let mut m = adj;
  let mut l: List<Edge> = m.get(a).unwrap_or([]);
  l.push(Edge { to: b, w: c });
  m.insert(a, l);
  m
}

fn dijkstra(adj: HashMap<Str, List<Edge>>, src: Str) -> HashMap<Str, Int> {
  let mut dist: HashMap<Str, Int> = HashMap::new();
  let mut done: HashMap<Str, Bool> = HashMap::new();
  dist.insert(src, 0);
  loop {
    let mut best = "";
    let mut bd = -1;
    for k in dist.keys() {
      if done.get(k).is_none() {
        let d = dist.get(k).unwrap_or(0);
        if bd < 0 || d < bd {
          bd = d;
          best = k;
        }
      }
    }
    if bd < 0 { break; }
    done.insert(best, true);
    let edges: List<Edge> = adj.get(best).unwrap_or([]);
    for e in edges {
      let nd = bd + e.w;
      let better = match dist.get(e.to) {
        Some(c) => nd < c,
        None => true,
      };
      if better { dist.insert(e.to, nd); }
    }
  }
  dist
}

fn plan(adj: HashMap<Str, List<Edge>>, t: Trip) -> Str {
  let dist = dijkstra(adj, t.to);
  let Some(total) = dist.get(t.from) else {
    return t.from + " " + t.to + " unreachable";
  };
  let mut path: List<Str> = [t.from];
  let mut cur = t.from;
  while cur != t.to {
    let dcur = dist.get(cur).unwrap_or(0);
    let edges: List<Edge> = adj.get(cur).unwrap_or([]);
    let mut found = false;
    let mut next = "";
    for e in edges {
      if let Some(d) = dist.get(e.to) {
        if d + e.w == dcur {
          if !found || e.to < next {
            found = true;
            next = e.to;
          }
        }
      }
    }
    if !found { break; }
    path.push(next);
    cur = next;
  }
  path.join(" -> ") + " " + total.to_str()
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("routes.txt")?.to_str();
  let mut adj: HashMap<Str, List<Edge>> = HashMap::new();
  let mut trips: List<Trip> = [];
  for line in text.lines() {
    let t = line.trim();
    if t.len() == 0 || t.starts_with("#") { continue; }
    let w = words(t);
    if w[0] == "road" && w.len() == 4 {
      let Some(c) = w[3].parse_int() else { continue; };
      adj = add_edge(adj, w[1], w[2], c);
      adj = add_edge(adj, w[2], w[1], c);
    } else if w[0] == "trip" && w.len() == 3 {
      trips.push(Trip { from: w[1], to: w[2] });
    }
  }
  let mut lines: List<Str> = [];
  for t in trips {
    lines.push(plan(adj, t));
  }
  Ok(lines.join("\n"))
}

struct Entry { path: Str, line: Str }

fn merge(base: Json, over: Json) -> Json {
  match over {
    Json::Obj(o) => {
      let empty: Map<Str, Json> = Map::new();
      let mut m: Map<Str, Json> = base.as_map().unwrap_or(empty);
      for k in o.keys() {
        let ov = o.get(k).unwrap_or(Json::Null);
        match ov {
          Json::Null => { m.remove(k); },
          _ => {
            let bv = m.get(k).unwrap_or(Json::Null);
            m.insert(k, merge(bv, ov));
          },
        }
      }
      Json::Obj(m)
    },
    _ => over,
  }
}

fn flatten(j: Json, path: Str, acc: List<Entry>) -> List<Entry> {
  let mut res = acc;
  match j {
    Json::Obj(m) => {
      if m.len() == 0 {
        res.push(Entry { path: path, line: path + "={}" });
      } else {
        for k in m.keys() {
          let p = if path == "" { k } else { path + "." + k };
          res = flatten(m.get(k).unwrap_or(Json::Null), p, res);
        }
      }
    },
    Json::Arr(a) => {
      if a.len() == 0 {
        res.push(Entry { path: path, line: path + "=[]" });
      } else {
        for i in 0..a.len() {
          let p = if path == "" { i.to_str() } else { path + "." + i.to_str() };
          res = flatten(a[i], p, res);
        }
      }
    },
    other => {
      res.push(Entry { path: path, line: path + "=" + other.to_json() });
    },
  }
  res
}

fn load(d: Dir, name: Str) -> Result<Json, Str> {
  let b = match d.read(name) {
    Ok(b) => b,
    Err(_) => return Err("cannot read " + name),
  };
  b.to_str().parse_json()
}

fn main(input: Dir) -> Result<Str, Str> {
  let base = load(input, "base.json")?;
  let over = load(input, "override.json")?;
  let merged = merge(base, over);
  let init: List<Entry> = [];
  let mut entries = flatten(merged, "", init);
  entries.sort_by_key(|e| e.path);
  let lines = entries.map(|e| e.line);
  Ok(lines.join("\n"))
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("app.log")?.to_str();
  let mut errs = "";
  let mut warns = "";
  let mut infos = "";
  let mut ne = 0;
  let mut nw = 0;
  let mut ni = 0;
  let mut other = 0;
  for line in text.lines() {
    if line.trim() == "" { continue; }
    let parts = line.split(" ");
    if parts.len() < 3 {
      other += 1;
      continue;
    }
    let level = parts[1].to_lowercase();
    if level == "error" {
      errs = errs + line + "\n";
      ne += 1;
    } else if level == "warn" || level == "warning" {
      warns = warns + line + "\n";
      nw += 1;
    } else if level == "info" {
      infos = infos + line + "\n";
      ni += 1;
    } else {
      other += 1;
    }
  }
  out.write("error.log", errs.to_bytes())?;
  out.write("warn.log", warns.to_bytes())?;
  out.write("info.log", infos.to_bytes())?;
  Ok("error " + ne.to_str() + "\nwarn " + nw.to_str() + "\ninfo " + ni.to_str() + "\nother " + other.to_str() + "\n")
}

struct Entry { path: Str, bytes: Int, lines: Int }

fn walk(d: Dir, prefix: Str, acc: List<Entry>) -> Result<List<Entry>, IoErr> {
  let mut res = acc;
  let dirpath = if prefix == "" { "" } else { prefix.slice(0, prefix.len() - 1) };
  let names = d.list(dirpath)?;
  for name in names {
    if name.ends_with("/") {
      res = walk(d, prefix + name, res)?;
    } else {
      let path = prefix + name;
      let data = d.read(path)?;
      let mut nl = 0;
      for b in data {
        if b == 10 { nl += 1; }
      }
      let n = data.len();
      if n > 0 && data[n - 1] != 10 { nl += 1; }
      res.push(Entry { path: path, bytes: n, lines: nl });
    }
  }
  Ok(res)
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let empty: List<Entry> = [];
  let mut entries = walk(input, "", empty)?;
  entries.sort_by_key(|e| e.path);
  let mut text = "path,bytes,lines\n";
  let mut total = 0;
  for e in entries {
    text = text + e.path + "," + e.bytes.to_str() + "," + e.lines.to_str() + "\n";
    total += e.bytes;
  }
  out.create("index.csv", text.to_bytes())?;
  Ok("files " + entries.len().to_str() + " bytes " + total.to_str())
}

fn parse_fields(line: Str) -> List<Str> {
  let cs = line.chars();
  let mut fields: List<Str> = [];
  let mut cur = "";
  let mut inq = false;
  let mut i = 0;
  while i < cs.len() {
    let c = cs[i];
    if inq {
      if c == "\"" {
        if i + 1 < cs.len() && cs[i + 1] == "\"" {
          cur = cur + "\"";
          i += 2;
          continue;
        } else {
          inq = false;
        }
      } else {
        cur = cur + c;
      }
    } else {
      if c == "\"" {
        inq = true;
      } else if c == "," {
        fields.push(cur);
        cur = "";
      } else {
        cur = cur + c;
      }
    }
    i += 1;
  }
  fields.push(cur);
  fields
}

fn is_active(s: Str) -> Bool {
  let l = s.to_lowercase();
  l == "yes" || l == "true" || l == "1"
}

fn parse_row(line: Str) -> Option<Json> {
  let f = parse_fields(line);
  if f.len() != 5 { return None; }
  let id = f[0].parse_int()?;
  let mut tags: List<Json> = [];
  for t in f[4].split(";") {
    let tt = t.trim();
    if tt.len() > 0 { tags.push(Json::Str(tt)); }
  }
  let mut obj: Map<Str, Json> = Map::new();
  obj.insert("id", Json::Num(id));
  obj.insert("name", Json::Str(f[1]));
  obj.insert("email", Json::Str(f[2]));
  obj.insert("active", Json::Bool(is_active(f[3])));
  obj.insert("tags", Json::Arr(tags));
  Some(Json::Obj(obj))
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("users.csv")?.to_str();
  let mut rows: List<Json> = [];
  let mut skipped = 0;
  let mut first = true;
  for line in text.lines() {
    if first {
      first = false;
      continue;
    }
    if line.trim().len() == 0 { continue; }
    match parse_row(line) {
      Some(j) => rows.push(j),
      None => { skipped += 1; }
    }
  }
  let n = rows.len();
  out.write("users.json", Json::Arr(rows).to_json().to_bytes())?;
  Ok("rows " + n.to_str() + " skipped " + skipped.to_str())
}

fn ch(c: Int) -> Str {
  let digits = "0123456789";
  let letters = "abcdefghijklmnopqrstuvwxyz";
  if c == 46 {
    "."
  } else if c <= 57 {
    digits.slice(c - 48, c - 47)
  } else {
    letters.slice(c - 97, c - 96)
  }
}

fn norm(name: Str) -> Str {
  let mut out = "";
  let mut pending = false;
  for b in name.to_bytes() {
    let mut c = b;
    if c >= 65 && c <= 90 {
      c = c + 32;
    }
    let ok = (c >= 97 && c <= 122) || (c >= 48 && c <= 57) || c == 46;
    if ok {
      if pending && out.len() > 0 {
        out = out + "-";
      }
      pending = false;
      out = out + ch(c);
    } else {
      pending = true;
    }
  }
  out
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let mut names = input.list("")?;
  names.sort();
  let mut taken: Map<Str, Bool> = Map::new();
  let mut lines: List<Str> = [];
  for name in names {
    let n = norm(name);
    if n.len() == 0 || taken.get(n).is_some() {
      lines.push(name + " skipped");
      continue;
    }
    taken.insert(n, true);
    let data = input.read(name)?;
    out.create(n, data)?;
    lines.push(name + " -> " + n);
  }
  Ok(lines.join("\n"))
}

fn is_part(name: Str) -> Bool {
  let Some(rest) = name.strip_prefix("part-") else { return false; };
  let Some(mid) = rest.strip_suffix(".txt") else { return false; };
  if mid.len() != 4 { return false; }
  for c in mid.chars() {
    if !"0123456789".contains(c) { return false; }
  }
  true
}

fn parse_part(text: Str) -> Option<List<Int>> {
  let mut vals: List<Int> = [];
  for line in text.lines() {
    let t = line.trim();
    if t.len() == 0 { continue; }
    let v = t.parse_int()?;
    vals.push(v);
  }
  Some(vals)
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let names = input.list("")?;
  let mut all: List<Int> = [];
  let mut parts = 0;
  let mut corrupt = 0;
  for name in names {
    if !is_part(name) { continue; }
    parts += 1;
    let text = input.read(name)?.to_str();
    match parse_part(text) {
      Some(v) => {
        for x in v { all.push(x); }
      }
      None => {
        corrupt += 1;
      }
    }
  }
  all.sort();
  let mut lines: List<Str> = [];
  let mut last: Option<Int> = None;
  for x in all {
    let dup = match last {
      Some(p) => p == x,
      None => false,
    };
    if !dup {
      lines.push(x.to_str());
      last = Some(x);
    }
  }
  let count = lines.len();
  let mut body = lines.join("\n");
  if count > 0 { body = body + "\n"; }
  out.create("merged.txt", body.to_bytes())?;
  Ok("parts " + parts.to_str() + " corrupt " + corrupt.to_str() + " values " + count.to_str())
}

fn main(src: Dir, dst: Dir) -> Result<Str, IoErr> {
  let sn = src.list("")?;
  let dn = dst.list("")?;
  let mut out = "";
  for name in sn {
    let data = src.read(name)?;
    if dn.contains(name) {
      let old = dst.read(name)?;
      if old == data {
        out = out + "same " + name + "\n";
      } else {
        dst.write(name, data)?;
        out = out + "updated " + name + "\n";
      }
    } else {
      dst.write(name, data)?;
      out = out + "added " + name + "\n";
    }
  }
  let mut kept = 0;
  for name in dn {
    if !sn.contains(name) {
      kept = kept + 1;
    }
  }
  out = out + "kept " + kept.to_str() + "\n";
  Ok(out)
}

struct Row { page: Str, total: Int }

fn main(input: Dir, counts: Kv) -> Result<Str, Str> {
  let text = input.read("visits.txt").map_err(|e| "cannot read visits.txt")?.to_str();
  let mut local: Map<Str, Int> = Map::new();
  for line in text.lines() {
    let p = line.trim();
    if p.len() == 0 { continue; }
    let n = local.get(p).unwrap_or(0);
    local.insert(p, n + 1);
  }
  for p in local.keys() {
    let n = local.get(p).unwrap_or(0);
    counts.add("visits:" + p, n).map_err(|e| "kv add failed")?;
  }
  let keys = counts.keys("visits:").map_err(|e| "kv keys failed")?;
  let mut rows: List<Row> = [];
  for k in keys {
    let v = counts.get(k).map_err(|e| "kv get failed")?;
    let total = match v {
      Some(b) => b.to_str().parse_int().unwrap_or(0),
      None => 0,
    };
    rows.push(Row { page: k.slice(7, k.len()), total: total });
  }
  rows.sort_by(|a, b| a.total > b.total || (a.total == b.total && a.page < b.page));
  let mut lines: List<Str> = [];
  for r in rows {
    lines.push(r.page + " " + r.total.to_str());
  }
  Ok(lines.join("\n"))
}

fn user_json(id: Str, name: Str, email: Str) -> Str {
  "{\"id\":" + Json::Str(id).to_json() + ",\"name\":" + Json::Str(name).to_json() + ",\"email\":" + Json::Str(email).to_json() + "}"
}

fn handle(users: Kv, line: Str) -> Result<Str, KvErr> {
  let parts = line.split(" ").filter(|p| p.len() > 0);
  let n = parts.len();
  let bad = "bad " + line;
  if n == 0 { return Ok(bad); }
  let cmd = parts[0];
  if cmd == "put" && n == 4 {
    let id = parts[1];
    users.set("user:" + id, (parts[2] + " " + parts[3]).to_bytes())?;
    return Ok("ok " + id);
  }
  if cmd == "rename" && n == 3 {
    let id = parts[1];
    let key = "user:" + id;
    return match users.get(key)? {
      None => Ok("missing " + id),
      Some(b) => {
        let v = b.to_str().split(" ");
        users.set(key, (parts[2] + " " + v[1]).to_bytes())?;
        Ok("ok " + id)
      }
    };
  }
  if cmd == "get" && n == 2 {
    let id = parts[1];
    return match users.get("user:" + id)? {
      None => Ok("missing " + id),
      Some(b) => {
        let v = b.to_str().split(" ");
        Ok(user_json(id, v[0], v[1]))
      }
    };
  }
  if cmd == "del" && n == 2 {
    let id = parts[1];
    let key = "user:" + id;
    return match users.get(key)? {
      None => Ok("missing " + id),
      Some(_) => {
        users.delete(key)?;
        Ok("ok " + id)
      }
    };
  }
  if cmd == "count" && n == 1 {
    let ks = users.keys("user:")?;
    return Ok("count " + ks.len().to_str());
  }
  Ok(bad)
}

fn main(input: Dir, users: Kv) -> Result<Str, Str> {
  let text = match input.read("commands.txt") {
    Ok(b) => b.to_str(),
    Err(_) => return Err("cannot read commands.txt"),
  };
  let mut out = "";
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 { continue; }
    match handle(users, line) {
      Ok(s) => { out = out + s + "\n"; }
      Err(_) => { return Err("kv error"); }
    }
  }
  Ok(out)
}

struct Ev { id: Str, account: Str, cents: Int }

fn parse_ev(line: Str) -> Option<Ev> {
  let j = match line.parse_json() {
    Ok(j) => j,
    Err(_) => return None,
  };
  let id = j.get("id").and_then(|x| x.as_str())?;
  let account = j.get("account").and_then(|x| x.as_str())?;
  let cents = j.get("cents").and_then(|x| x.as_int())?;
  Some(Ev { id: id, account: account, cents: cents })
}

// 0 = rejected, 1 = applied, 2 = duplicate
fn apply(state: Kv, ev: Ev) -> Result<Int, KvErr> {
  if ("seen/" + ev.id).len() > 1024 || ("bal/" + ev.account).len() > 1024 {
    return Ok(0);
  }
  let claimed = state.swap("seen/" + ev.id, None, Some("1".to_bytes()))?;
  if !claimed { return Ok(2); }
  state.add("bal/" + ev.account, ev.cents)?;
  Ok(1)
}

fn main(input: Dir, state: Kv) -> Result<Str, Str> {
  let text = input.read("events.jsonl").map_err(|_e| "read failed")?.to_str();
  let mut applied = 0;
  let mut dup = 0;
  let mut rejected = 0;
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 { continue; }
    let Some(ev) = parse_ev(line) else {
      rejected += 1;
      continue;
    };
    let r = apply(state, ev).map_err(|_e| "kv error")?;
    if r == 1 { applied += 1; }
    else if r == 2 { dup += 1; }
    else { rejected += 1; }
  }
  let mut out = "applied " + applied.to_str() + " duplicate " + dup.to_str() + " rejected " + rejected.to_str() + "\n";
  let mut after: Option<Str> = None;
  loop {
    let page = state.scan("bal/", after, 1000).map_err(|_e| "kv error")?;
    for e in page {
      out = out + e.key.slice(4, e.key.len()) + " " + e.value.to_str() + "\n";
      after = Some(e.key);
    }
    if page.len() < 1000 { break; }
  }
  Ok(out)
}

fn main(input: Dir, limits: Kv) -> Result<Str, Str> {
  let data = match input.read("requests.txt") {
    Ok(b) => b,
    Err(_) => return Err("cannot read requests.txt"),
  };
  let text = data.to_str();
  let mut out = "";
  for line in text.lines() {
    let mut parts: List<Str> = [];
    for p in line.trim().split(" ") {
      if p.len() > 0 { parts.push(p); }
    }
    if parts.len() != 2 { continue; }
    let Some(t) = parts[0].parse_int() else { continue; };
    let client = parts[1];
    let key = (t / 60).to_str() + " " + client;
    let cur = match limits.get(key) {
      Ok(Some(b)) => b.to_str().parse_int().unwrap_or(0),
      Ok(None) => 0,
      Err(_) => return Err("kv get failed"),
    };
    let prefix = parts[0] + " " + client;
    if cur < 3 {
      match limits.add(key, 1) {
        Ok(_) => {},
        Err(_) => return Err("kv add failed"),
      }
      out = out + prefix + " allow\n";
    } else {
      out = out + prefix + " deny\n";
    }
  }
  Ok(out)
}

struct Stat { name: Str, points: Int, played: Int }

fn bump(m: Map<Str, Stat>, name: Str, pts: Int) -> Map<Str, Stat> {
  let mut out = m;
  let cur = match out.get(name) {
    Some(s) => s,
    None => Stat { name: name, points: 0, played: 0 },
  };
  out.insert(name, Stat { name: name, points: cur.points + pts, played: cur.played + 1 });
  out
}

fn less(a: Stat, b: Stat) -> Bool {
  if a.points != b.points { return a.points > b.points; }
  if a.played != b.played { return a.played < b.played; }
  a.name < b.name
}

fn load(board: Kv) -> Result<Map<Str, Stat>, Str> {
  let mut stats: Map<Str, Stat> = Map::new();
  let mut after: Option<Str> = None;
  loop {
    let page = match board.scan("p/", after, 1000) {
      Ok(p) => p,
      Err(_) => { return Err("kv scan failed"); }
    };
    for e in page {
      let name = e.key.slice(2, e.key.len());
      let parts = e.value.to_str().split(",");
      if parts.len() == 2 {
        let pts = parts[0].parse_int().unwrap_or(0);
        let pl = parts[1].parse_int().unwrap_or(0);
        stats.insert(name, Stat { name: name, points: pts, played: pl });
      }
    }
    if page.len() < 1000 { break; }
    after = Some(page[page.len() - 1].key);
  }
  Ok(stats)
}

fn main(input: Dir, board: Kv) -> Result<Str, Str> {
  let mut stats = load(board)?;
  let text = match input.read("games.txt") {
    Ok(b) => b.to_str(),
    Err(_) => "",
  };
  let mut touched: Map<Str, Bool> = Map::new();
  for raw in text.lines() {
    let line = raw.trim();
    let parts = line.split(" ");
    if parts.len() == 2 {
      if parts[0] != "" && parts[1] != "" {
        stats = bump(stats, parts[0], 3);
        stats = bump(stats, parts[1], 0);
        touched.insert(parts[0], true);
        touched.insert(parts[1], true);
      }
    } else if parts.len() == 3 {
      if parts[2] == "draw" && parts[0] != "" && parts[1] != "" {
        stats = bump(stats, parts[0], 1);
        stats = bump(stats, parts[1], 1);
        touched.insert(parts[0], true);
        touched.insert(parts[1], true);
      }
    }
  }
  for name in touched.keys() {
    let Some(s) = stats.get(name) else { continue; };
    let val = s.points.to_str() + "," + s.played.to_str();
    match board.set("p/" + name, val.to_bytes()) {
      Ok(_) => {},
      Err(_) => { return Err("kv set failed"); }
    }
  }
  let mut all: List<Stat> = [];
  for name in stats.keys() {
    let Some(s) = stats.get(name) else { continue; };
    all.push(s);
  }
  all.sort_by(less);
  let mut lines: List<Str> = [];
  let mut i = 0;
  while i < 3 && i < all.len() {
    let s = all[i];
    lines.push((i + 1).to_str() + ". " + s.name + " " + s.points.to_str() + " " + s.played.to_str());
    i += 1;
  }
  Ok(lines.join("\n"))
}

fn cell(v: SqlValue) -> Str {
  match v {
    SqlValue::Int(n) => n.to_str(),
    SqlValue::Text(s) => s,
    SqlValue::Float(f) => f.to_str(),
    _ => "",
  }
}

fn main(input: Dir, shop: Db) -> Result<Str, Str> {
  let text = input.read("orders.csv").map_err(|e| "cannot read orders.csv")?.to_str();
  let c = shop.exec("CREATE TABLE IF NOT EXISTS orders (order_id INTEGER PRIMARY KEY, customer TEXT NOT NULL, product TEXT NOT NULL, qty INTEGER NOT NULL, unit_cents INTEGER NOT NULL)", []).map_err(|e| "db error")?;
  let mut imported = 0;
  let mut skipped = 0;
  let mut rejected = 0;
  let mut first = true;
  for line in text.lines() {
    if first {
      first = false;
      continue;
    }
    if line.trim().len() == 0 { continue; }
    let parts = line.split(",");
    if parts.len() != 5 {
      rejected += 1;
      continue;
    }
    let Some(id) = parts[0].trim().parse_int() else {
      rejected += 1;
      continue;
    };
    let Some(qty) = parts[3].trim().parse_int() else {
      rejected += 1;
      continue;
    };
    let Some(unit) = parts[4].trim().parse_int() else {
      rejected += 1;
      continue;
    };
    let n = shop.exec(
      "INSERT OR IGNORE INTO orders (order_id, customer, product, qty, unit_cents) VALUES (?, ?, ?, ?, ?)",
      [SqlValue::Int(id), SqlValue::Text(parts[1]), SqlValue::Text(parts[2]), SqlValue::Int(qty), SqlValue::Int(unit)]
    ).map_err(|e| "db error")?;
    if n == 0 { skipped += 1; } else { imported += 1; }
  }
  let mut out = "imported " + imported.to_str() + " skipped " + skipped.to_str() + " rejected " + rejected.to_str();
  let rows = shop.query(
    "SELECT product, SUM(qty * unit_cents) AS rev, COUNT(*) FROM orders GROUP BY product ORDER BY rev DESC, product ASC LIMIT 3",
    []
  ).map_err(|e| "db error")?;
  for r in rows {
    out = out + "\n" + cell(r[0]) + " " + cell(r[1]) + " " + cell(r[2]);
  }
  Ok(out)
}

struct Agg { country: Str, customers: Int, orders: Int, revenue: Int, top_name: Str, top_rev: Int }

fn int_of(v: SqlValue) -> Option<Int> {
  match v {
    SqlValue::Int(i) => Some(i),
    _ => None,
  }
}

fn text_of(v: SqlValue) -> Option<Str> {
  match v {
    SqlValue::Text(s) => Some(s),
    _ => None,
  }
}

fn main(shop: Db) -> Result<Str, Str> {
  let sql = "SELECT c.country, c.id, c.name, COUNT(*), SUM(o.total_cents) FROM orders o JOIN customers c ON c.id = o.customer_id WHERE o.status = 'paid' AND o.placed >= '2026-01-01' AND o.placed < '2027-01-01' GROUP BY c.id ORDER BY c.id";
  let rows = shop.query(sql, []).map_err(|e| "query failed")?;
  let mut m: Map<Str, Agg> = Map::new();
  let mut total_orders = 0;
  let mut total_rev = 0;
  for r in rows {
    if r.len() != 5 { return Err("bad row"); }
    let Some(country) = text_of(r[0]) else { return Err("bad country"); };
    let Some(name) = text_of(r[2]) else { return Err("bad name"); };
    let Some(cnt) = int_of(r[3]) else { return Err("bad count"); };
    let Some(rev) = int_of(r[4]) else { return Err("bad sum"); };
    let mut a = match m.get(country) {
      Some(x) => x,
      None => Agg { country: country, customers: 0, orders: 0, revenue: 0, top_name: "", top_rev: -1 },
    };
    a.customers = a.customers + 1;
    a.orders = a.orders + cnt;
    a.revenue = a.revenue + rev;
    if rev > a.top_rev {
      a.top_rev = rev;
      a.top_name = name;
    }
    m.insert(country, a);
    total_orders = total_orders + cnt;
    total_rev = total_rev + rev;
  }
  let mut list: List<Agg> = [];
  for k in m.keys() {
    if let Some(a) = m.get(k) { list.push(a); }
  }
  list.sort_by(|a, b| a.revenue > b.revenue || (a.revenue == b.revenue && a.country < b.country));
  let mut lines: List<Str> = [];
  for a in list {
    lines.push(a.country + " customers=" + a.customers.to_str() + " orders=" + a.orders.to_str() + " revenue=" + a.revenue.to_str() + " top=" + a.top_name);
  }
  lines.push("total orders=" + total_orders.to_str() + " revenue=" + total_rev.to_str());
  Ok(lines.join("\n"))
}

struct Move { sku: Str, delta: Int }
struct Batch { name: Str, moves: List<Move>, bad: Bool }

fn parse_move(line: Str) -> Option<Move> {
  let parts = line.split(" ");
  if parts.len() != 2 { return None; }
  let sku = parts[0];
  let amt = parts[1];
  if sku.len() == 0 { return None; }
  let mut sign = 1;
  let mut rest = "";
  if let Some(r) = amt.strip_prefix("+") {
    rest = r;
  } else if let Some(r) = amt.strip_prefix("-") {
    rest = r;
    sign = -1;
  } else {
    return None;
  }
  if rest.len() == 0 { return None; }
  for b in rest.to_bytes() {
    if b < 48 || b > 57 { return None; }
  }
  let n = rest.parse_int()?;
  if n <= 0 { return None; }
  Some(Move { sku: sku, delta: sign * n })
}

fn parse(text: Str) -> List<Batch> {
  let mut batches: List<Batch> = [];
  let mut has = false;
  let mut name = "";
  let mut moves: List<Move> = [];
  let mut bad = false;
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 { continue; }
    if let Some(n) = line.strip_prefix("batch ") {
      if has {
        batches.push(Batch { name: name, moves: moves, bad: bad });
      }
      has = true;
      name = n.trim();
      moves = [];
      bad = false;
    } else {
      if !has { continue; }
      match parse_move(line) {
        Some(m) => { moves.push(m); }
        None => { bad = true; }
      }
    }
  }
  if has {
    batches.push(Batch { name: name, moves: moves, bad: bad });
  }
  batches
}

fn is_applied(db: Db, name: Str) -> Result<Bool, DbErr> {
  let rows = db.query("SELECT 1 FROM applied WHERE name = ?", [SqlValue::Text(name)])?;
  Ok(rows.len() > 0)
}

fn qty(db: Db, sku: Str) -> Result<Int, DbErr> {
  let rows = db.query("SELECT qty FROM stock WHERE sku = ?", [SqlValue::Text(sku)])?;
  if rows.len() == 0 { return Ok(0); }
  match rows[0][0] {
    SqlValue::Int(n) => Ok(n),
    _ => Ok(0),
  }
}

fn process(db: Db, b: Batch) -> Result<Bool, DbErr> {
  if b.bad { return Ok(false); }
  let mut cur: Map<Str, Int> = Map::new();
  for m in b.moves {
    let base = match cur.get(m.sku) {
      Some(v) => v,
      None => qty(db, m.sku)?,
    };
    let n = base + m.delta;
    if n < 0 { return Ok(false); }
    cur.insert(m.sku, n);
  }
  let mut stmts: List<Str> = [];
  let mut params: List<List<SqlValue>> = [];
  for k in cur.keys() {
    stmts.push("INSERT INTO stock(sku, qty) VALUES(?, ?) ON CONFLICT(sku) DO UPDATE SET qty = excluded.qty");
    params.push([SqlValue::Text(k), SqlValue::Int(cur.get(k).unwrap_or(0))]);
  }
  stmts.push("INSERT INTO applied(name) VALUES(?)");
  params.push([SqlValue::Text(b.name)]);
  db.transaction(stmts, params)?;
  Ok(true)
}

fn main(input: Dir, stock: Db) -> Result<Str, DbErr> {
  stock.exec("CREATE TABLE IF NOT EXISTS applied(name TEXT PRIMARY KEY)", [])?;
  stock.exec("CREATE TABLE IF NOT EXISTS stock(sku TEXT PRIMARY KEY, qty INTEGER NOT NULL)", [])?;
  let text = match input.read("moves.txt") {
    Ok(b) => b.to_str(),
    Err(_) => "",
  };
  let batches = parse(text);
  let mut out = "";
  for b in batches {
    if is_applied(stock, b.name)? {
      out = out + b.name + " skipped\n";
    } else if process(stock, b)? {
      out = out + b.name + " applied\n";
    } else {
      out = out + b.name + " rejected\n";
    }
  }
  let rows = stock.query("SELECT sku, qty FROM stock WHERE qty != 0 ORDER BY sku", [])?;
  for r in rows {
    let sku = match r[0] {
      SqlValue::Text(s) => s,
      _ => "",
    };
    let q = match r[1] {
      SqlValue::Int(n) => n,
      _ => 0,
    };
    out = out + sku + " " + q.to_str() + "\n";
  }
  Ok(out)
}

fn text_of(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn sync(crm: Db, text: Str) -> Result<Str, DbErr> {
  let made = crm.exec("CREATE TABLE IF NOT EXISTS contacts (email TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL)", [])?;
  let lines = text.lines();
  let mut inserted = 0;
  let mut updated = 0;
  let mut unchanged = 0;
  let mut rejected = 0;
  for i in 1..lines.len() {
    let line = lines[i];
    if line.trim() == "" { continue; }
    let parts = line.split(",");
    if parts.len() != 3 { rejected += 1; continue; }
    let email = parts[0].trim().to_lowercase();
    let name = parts[1].trim();
    let phone = parts[2].trim();
    if !email.contains("@") { rejected += 1; continue; }
    let rows = crm.query("SELECT name, phone FROM contacts WHERE email = ?", [SqlValue::Text(email)])?;
    if rows.len() == 0 {
      let n = crm.exec("INSERT INTO contacts (email, name, phone) VALUES (?, ?, ?)", [SqlValue::Text(email), SqlValue::Text(name), SqlValue::Text(phone)])?;
      inserted += 1;
    } else {
      let old_name = text_of(rows[0][0]);
      let old_phone = text_of(rows[0][1]);
      if old_name != name || old_phone != phone {
        let n = crm.exec("UPDATE contacts SET name = ?, phone = ? WHERE email = ?", [SqlValue::Text(name), SqlValue::Text(phone), SqlValue::Text(email)])?;
        updated += 1;
      } else {
        unchanged += 1;
      }
    }
  }
  let counts = crm.query("SELECT COUNT(*) FROM contacts", [])?;
  let total = match counts[0][0] {
    SqlValue::Int(n) => n,
    _ => 0,
  };
  let mut out = "inserted " + inserted.to_str() + " updated " + updated.to_str() + " unchanged " + unchanged.to_str() + " rejected " + rejected.to_str();
  out = out + "\ncontacts " + total.to_str();
  let missing = crm.query("SELECT email FROM contacts WHERE phone = '' ORDER BY email", [])?;
  for r in missing {
    out = out + "\nmissing phone: " + text_of(r[0]);
  }
  Ok(out)
}

fn main(input: Dir, crm: Db) -> Result<Str, Str> {
  let bytes = match input.read("contacts.csv") {
    Ok(b) => b,
    Err(_) => return Err("cannot read contacts.csv"),
  };
  match sync(crm, bytes.to_str()) {
    Ok(s) => Ok(s),
    Err(_) => Err("database error"),
  }
}

struct Entry { name: Str, count: Int }

fn valid(name: Str) -> Bool {
  let n = name.len();
  if n < 1 || n > 32 { return false; }
  for c in name.chars() {
    let ok = (c >= "a" && c <= "z") || (c >= "0" && c <= "9") || c == "-";
    if !ok { return false; }
  }
  true
}

fn reply(res: Outgoing, status: Int, body: Str) -> Str {
  match res.send(status, ["content-type"], ["application/json"], body.to_bytes()) {
    Ok(_) => "ok",
    Err(_) => "send failed",
  }
}

fn obj(name: Str, n: Int) -> Str {
  "{\"name\": \"" + name + "\", \"count\": " + n.to_str() + "}"
}

fn internal(res: Outgoing) -> Str {
  reply(res, 500, "{\"error\": \"internal\"}")
}

fn count_of(counts: Kv, name: Str) -> Result<Int, KvErr> {
  let v = counts.get("c/" + name)?;
  match v {
    Some(b) => Ok(b.to_str().parse_int().unwrap_or(0)),
    None => Ok(0),
  }
}

fn top(counts: Kv) -> Result<List<Entry>, KvErr> {
  let mut all: List<Entry> = [];
  let mut after: Option<Str> = None;
  loop {
    let page = counts.scan("c/", after, 1000)?;
    for e in page {
      all.push(Entry { name: e.key.slice(2, e.key.len()), count: e.value.to_str().parse_int().unwrap_or(0) });
    }
    if page.len() < 1000 { break; }
    after = Some(page[page.len() - 1].key);
  }
  all.sort_by(|a, b| a.count > b.count || (a.count == b.count && a.name < b.name));
  Ok(all.slice(0, all.len().min(3)))
}

fn main(req: Incoming, res: Outgoing, counts: Kv) -> Str {
  let m = req.method();
  let t = req.target();
  if m == "POST" {
    if let Some(name) = t.strip_prefix("/hit/") {
      if !valid(name) { return reply(res, 400, "{\"error\": \"bad name\"}"); }
      return match counts.add("c/" + name, 1) {
        Ok(n) => reply(res, 200, obj(name, n)),
        Err(_) => internal(res),
      };
    }
  }
  if m == "GET" {
    if let Some(name) = t.strip_prefix("/count/") {
      if !valid(name) { return reply(res, 400, "{\"error\": \"bad name\"}"); }
      return match count_of(counts, name) {
        Ok(n) => reply(res, 200, obj(name, n)),
        Err(_) => internal(res),
      };
    }
    if t == "/top" {
      return match top(counts) {
        Ok(items) => {
          let mut parts: List<Str> = [];
          for e in items { parts.push(obj(e.name, e.count)); }
          reply(res, 200, "[" + parts.join(", ") + "]")
        },
        Err(_) => internal(res),
      };
    }
  }
  reply(res, 404, "{\"error\": \"not found\"}")
}

struct Resp { status: Int, body: Str }

fn error_resp(status: Int, msg: Str) -> Resp {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Resp { status: status, body: Json::Obj(m).to_json() }
}

fn not_found() -> Resp { error_resp(404, "not found") }

fn todo_json(id: Int, title: Str, done: Bool) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(id));
  m.insert("title", Json::Str(title));
  m.insert("done", Json::Bool(done));
  Json::Obj(m)
}

fn todo_key(id: Int) -> Str {
  let mut s = id.to_str();
  while s.len() < 12 { s = "0" + s; }
  "todo/" + s
}

fn parse_id(s: Str) -> Option<Int> {
  match s.parse_int() {
    Some(n) => if n >= 1 && n.to_str() == s { Some(n) } else { None },
    None => None,
  }
}

fn valid_utf8(b: Bytes) -> Bool {
  let n = b.len();
  let mut i = 0;
  while i < n {
    let c = b[i];
    if c < 128 { i += 1; continue; }
    let mut need = 0;
    let mut lo = 128;
    let mut hi = 191;
    if c >= 194 && c <= 223 { need = 1; }
    else if c == 224 { need = 2; lo = 160; }
    else if c == 237 { need = 2; hi = 159; }
    else if c >= 225 && c <= 239 { need = 2; }
    else if c == 240 { need = 3; lo = 144; }
    else if c == 244 { need = 3; hi = 143; }
    else if c >= 241 && c <= 243 { need = 3; }
    else { return false; }
    if i + need >= n { return false; }
    let c1 = b[i + 1];
    if c1 < lo || c1 > hi { return false; }
    let mut k = 2;
    while k <= need {
      let ck = b[i + k];
      if ck < 128 || ck > 191 { return false; }
      k += 1;
    }
    i += need + 1;
  }
  true
}

fn create(req: Incoming, store: Kv) -> Result<Resp, KvErr> {
  let bad = error_resp(400, "title required");
  let raw = req.body();
  if !valid_utf8(raw) { return Ok(bad); }
  let Ok(j) = raw.to_str().parse_json() else { return Ok(bad); };
  if j.as_map().is_none() { return Ok(bad); }
  let Some(t) = j.get("title").and_then(|x| x.as_str()) else { return Ok(bad); };
  let title = t.trim();
  if title.len() == 0 { return Ok(bad); }
  let id = store.add("seq", 1)?;
  let body = todo_json(id, title, false).to_json();
  store.set(todo_key(id), body.to_bytes())?;
  Ok(Resp { status: 201, body: body })
}

fn list(store: Kv, query: Str) -> Result<Resp, KvErr> {
  let mut want: Option<Bool> = None;
  for q in query.split("&") {
    if q == "done=true" { want = Some(true); }
    else if q == "done=false" { want = Some(false); }
  }
  let mut items: List<Json> = [];
  let mut after: Option<Str> = None;
  loop {
    let page = store.scan("todo/", after, 1000)?;
    for e in page {
      after = Some(e.key);
      if let Ok(j) = e.value.to_str().parse_json() {
        let done = j.get("done").and_then(|x| x.as_bool()).unwrap_or(false);
        let keep = match want {
          None => true,
          Some(w) => w == done,
        };
        if keep { items.push(j); }
      }
    }
    if page.len() < 1000 { break; }
  }
  Ok(Resp { status: 200, body: Json::Arr(items).to_json() })
}

fn get_one(store: Kv, id: Int) -> Result<Resp, KvErr> {
  match store.get(todo_key(id))? {
    None => Ok(not_found()),
    Some(b) => Ok(Resp { status: 200, body: b.to_str() }),
  }
}

fn patch(req: Incoming, store: Kv, id: Int) -> Result<Resp, KvErr> {
  let k = todo_key(id);
  if store.get(k)?.is_none() { return Ok(not_found()); }
  let bad = error_resp(400, "bad update");
  let raw = req.body();
  if !valid_utf8(raw) { return Ok(bad); }
  let Ok(j) = raw.to_str().parse_json() else { return Ok(bad); };
  if j.as_map().is_none() { return Ok(bad); }
  let mut new_title: Option<Str> = None;
  let mut new_done: Option<Bool> = None;
  if let Some(t) = j.get("title") {
    match t.as_str() {
      Some(s) => {
        let trimmed = s.trim();
        if trimmed.len() == 0 { return Ok(bad); }
        new_title = Some(trimmed);
      }
      None => return Ok(bad),
    }
  }
  if let Some(d) = j.get("done") {
    match d.as_bool() {
      Some(b) => { new_done = Some(b); }
      None => return Ok(bad),
    }
  }
  loop {
    let Some(old) = store.get(k)? else { return Ok(not_found()); };
    let oj = old.to_str().parse_json().unwrap_or(Json::Null);
    let title = match new_title {
      Some(s) => s,
      None => oj.get("title").and_then(|x| x.as_str()).unwrap_or(""),
    };
    let done = match new_done {
      Some(b) => b,
      None => oj.get("done").and_then(|x| x.as_bool()).unwrap_or(false),
    };
    let body = todo_json(id, title, done).to_json();
    if store.swap(k, Some(old), Some(body.to_bytes()))? {
      return Ok(Resp { status: 200, body: body });
    }
  }
}

fn delete(store: Kv, id: Int) -> Result<Resp, KvErr> {
  let k = todo_key(id);
  loop {
    let Some(old) = store.get(k)? else { return Ok(not_found()); };
    if store.swap(k, Some(old), None)? {
      return Ok(Resp { status: 204, body: "" });
    }
  }
}

fn route(req: Incoming, store: Kv) -> Result<Resp, KvErr> {
  let target = req.target();
  let mut path = target;
  let mut query = "";
  if let Some(i) = target.find("?") {
    path = target.slice(0, i);
    query = target.slice(i + 1, target.len());
  }
  let parts = path.split("/");
  let method = req.method();
  if parts.len() == 2 && parts[0] == "" && parts[1] == "todos" {
    match method {
      "POST" => create(req, store),
      "GET" => list(store, query),
      _ => Ok(not_found()),
    }
  } else if parts.len() == 3 && parts[0] == "" && parts[1] == "todos" {
    let Some(id) = parse_id(parts[2]) else { return Ok(not_found()); };
    match method {
      "GET" => get_one(store, id),
      "PATCH" => patch(req, store, id),
      "DELETE" => delete(store, id),
      _ => Ok(not_found()),
    }
  } else {
    Ok(not_found())
  }
}

fn main(req: Incoming, res: Outgoing, store: Kv) -> Result<Str, WebErr> {
  let r = match route(req, store) {
    Ok(r) => r,
    Err(_) => error_resp(500, "internal error"),
  };
  if r.status == 204 {
    res.send(204, [], [], "".to_bytes())?;
  } else {
    res.send(r.status, ["content-type"], ["application/json"], r.body.to_bytes())?;
  }
  Ok("")
}

struct Resp { status: Int, body: Json }

struct NewNote { title: Str, body: Str, tags: List<Str> }

fn obj1(k: Str, v: Json) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert(k, v);
  Json::Obj(m)
}

fn not_found() -> Resp {
  Resp { status: 404, body: obj1("error", Json::Str("not found")) }
}

fn int_at(row: List<SqlValue>, i: Int) -> Int {
  match row[i] {
    SqlValue::Int(n) => n,
    _ => 0,
  }
}

fn text_at(row: List<SqlValue>, i: Int) -> Str {
  match row[i] {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn tags_of(s: Str) -> List<Str> {
  let Ok(j) = s.parse_json() else { return []; };
  let l = j.as_list().unwrap_or([]);
  let mut out: List<Str> = [];
  for x in l { out.push(x.as_str().unwrap_or("")); }
  out
}

fn tags_json(tags: List<Str>) -> Json {
  let mut out: List<Json> = [];
  for t in tags { out.push(Json::Str(t)); }
  Json::Arr(out)
}

fn note_json(row: List<SqlValue>) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(int_at(row, 0)));
  m.insert("title", Json::Str(text_at(row, 1)));
  m.insert("body", Json::Str(text_at(row, 2)));
  m.insert("tags", tags_json(tags_of(text_at(row, 3))));
  Json::Obj(m)
}

fn parse_note(text: Str) -> Option<NewNote> {
  let Ok(doc) = text.parse_json() else { return None; };
  let Some(obj) = doc.as_map() else { return None; };
  let Some(title) = obj.get("title").and_then(|j| j.as_str()) else { return None; };
  if title.len() == 0 { return None; }
  let Some(body) = obj.get("body").and_then(|j| j.as_str()) else { return None; };
  let mut tags: List<Str> = [];
  match obj.get("tags") {
    None => {},
    Some(t) => {
      let Some(items) = t.as_list() else { return None; };
      for it in items {
        let Some(s) = it.as_str() else { return None; };
        let l = s.to_lowercase();
        if !tags.contains(l) { tags.push(l); }
      }
    },
  }
  Some(NewNote { title: title, body: body, tags: tags })
}

fn parse_id(s: Str) -> Option<Int> {
  let Some(n) = s.parse_int() else { return None; };
  if n.to_str() == s { Some(n) } else { None }
}

fn create(req: Incoming, db: Db) -> Result<Resp, DbErr> {
  let bad = Resp { status: 400, body: obj1("error", Json::Str("invalid note")) };
  let bytes = req.body();
  let text = bytes.to_str();
  let Some(n) = parse_note(text) else { return Ok(bad); };
  let rows = db.query(
    "INSERT INTO notes(title, body, tags) VALUES (?, ?, ?) RETURNING id",
    [SqlValue::Text(n.title), SqlValue::Text(n.body), SqlValue::Text(tags_json(n.tags).to_json())]
  )?;
  let id = int_at(rows[0], 0);
  Ok(Resp { status: 201, body: obj1("id", Json::Num(id)) })
}

fn list(query: Str, db: Db) -> Result<Resp, DbErr> {
  let mut tag: Option<Str> = None;
  let mut q: Option<Str> = None;
  for p in query.split("&") {
    if let Some(i) = p.find("=") {
      let k = p.slice(0, i);
      let v = p.slice(i + 1, p.len());
      if k == "tag" { tag = Some(v.to_lowercase()); }
      else if k == "q" { q = Some(v); }
    }
  }
  let rows = db.query("SELECT id, title, body, tags FROM notes ORDER BY id DESC", [])?;
  let mut items: List<Json> = [];
  for row in rows {
    if let Some(t) = tag {
      if !tags_of(text_at(row, 3)).contains(t) { continue; }
    }
    if let Some(w) = q {
      if !(text_at(row, 1).contains(w) || text_at(row, 2).contains(w)) { continue; }
    }
    let mut m: Map<Str, Json> = Map::new();
    m.insert("id", Json::Num(int_at(row, 0)));
    m.insert("title", Json::Str(text_at(row, 1)));
    items.push(Json::Obj(m));
  }
  Ok(Resp { status: 200, body: Json::Arr(items) })
}

fn handle(req: Incoming, db: Db) -> Result<Resp, DbErr> {
  db.exec(
    "CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, body TEXT NOT NULL, tags TEXT NOT NULL)",
    []
  )?;
  let target = req.target();
  let path = match target.find("?") {
    Some(i) => target.slice(0, i),
    None => target,
  };
  let query = match target.find("?") {
    Some(i) => target.slice(i + 1, target.len()),
    None => "",
  };
  let method = req.method();
  let parts = path.split("/");
  if parts.len() < 2 || parts[0] != "" || parts[1] != "notes" { return Ok(not_found()); }
  if parts.len() == 2 {
    if method == "POST" { return create(req, db); }
    if method == "GET" { return list(query, db); }
    return Ok(not_found());
  }
  if parts.len() == 3 {
    let Some(id) = parse_id(parts[2]) else { return Ok(not_found()); };
    if method == "GET" {
      let rows = db.query("SELECT id, title, body, tags FROM notes WHERE id = ?", [SqlValue::Int(id)])?;
      if rows.len() == 0 { return Ok(not_found()); }
      return Ok(Resp { status: 200, body: note_json(rows[0]) });
    }
    if method == "DELETE" {
      let n = db.exec("DELETE FROM notes WHERE id = ?", [SqlValue::Int(id)])?;
      if n == 0 { return Ok(not_found()); }
      return Ok(Resp { status: 200, body: obj1("deleted", Json::Num(id)) });
    }
  }
  Ok(not_found())
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Result<Str, WebErr> {
  let r = match handle(req, db) {
    Ok(r) => r,
    Err(_) => Resp { status: 500, body: obj1("error", Json::Str("internal error")) },
  };
  res.send(r.status, ["content-type"], ["application/json"], r.body.to_json().to_bytes())?;
  Ok("done")
}

struct Line { name: Str, text: Str }

fn tenths(n: Int) -> Str {
  let a = if n < 0 { 0 - n } else { n };
  let sign = if n < 0 { "-" } else { "" };
  sign + (a / 10).to_str() + "." + (a % 10).to_str()
}

fn summarize(api: Http, name: Str, id: Str) -> Str {
  let body = match api.get("/stations/" + id + "/readings") {
    Ok(b) => b,
    Err(_) => return name + " unavailable",
  };
  let Ok(doc) = body.to_str().parse_json() else { return name + " unavailable"; };
  let rs = doc.get("readings").and_then(|j| j.as_list()).unwrap_or([]);
  let mut n = 0;
  let mut sum = 0;
  let mut lo = 0;
  let mut hi = 0;
  for r in rs {
    let Some(t) = r.get("temp").and_then(|j| j.as_int()) else { continue; };
    if n == 0 {
      lo = t;
      hi = t;
    } else {
      if t < lo { lo = t; }
      if t > hi { hi = t; }
    }
    n += 1;
    sum += t;
  }
  if n == 0 {
    return name + " no data";
  }
  let avg = sum / n;
  name + " min=" + tenths(lo) + " max=" + tenths(hi) + " avg=" + tenths(avg) + " n=" + n.to_str()
}

fn main(api: Http) -> Result<Str, Str> {
  let body = match api.get("/stations") {
    Ok(b) => b,
    Err(_) => return Err("stations request failed"),
  };
  let doc = body.to_str().parse_json()?;
  let stations = doc.get("stations").and_then(|j| j.as_list()).unwrap_or([]);
  let mut lines: List<Line> = [];
  for s in stations {
    let Some(id) = s.get("id").and_then(|j| j.as_str()) else { continue; };
    let Some(name) = s.get("name").and_then(|j| j.as_str()) else { continue; };
    lines.push(Line { name: name, text: summarize(api, name, id) });
  }
  lines.sort_by_key(|l| l.name);
  let texts = lines.map(|l| l.text);
  Ok(texts.join("\n"))
}

fn fetch(api: Http, page: Int) -> Result<Json, Str> {
  let path = "/orders?page=" + page.to_str();
  let bytes = match api.get(path) {
    Ok(b) => b,
    Err(_) => return Err("get failed"),
  };
  bytes.to_str().parse_json()
}

fn main(api: Http) -> Result<Str, Str> {
  let mut paid: Map<Str, Int> = Map::new();
  let mut count = 0;
  let mut refunded = 0;
  let mut have = false;
  let mut best_id = 0;
  let mut best_cents = 0;
  let mut page = 1;
  let mut done = false;
  while !done {
    let doc = fetch(api, page)?;
    let orders = doc.get("orders").and_then(|j| j.as_list()).unwrap_or([]);
    for o in orders {
      count += 1;
      let id = o.get("id").and_then(|j| j.as_int()).unwrap_or(0);
      let status = o.get("status").and_then(|j| j.as_str()).unwrap_or("");
      let cents = o.get("cents").and_then(|j| j.as_int()).unwrap_or(0);
      let currency = o.get("currency").and_then(|j| j.as_str()).unwrap_or("");
      if status == "refunded" {
        refunded += 1;
      }
      if status == "paid" {
        let cur = paid.get(currency).unwrap_or(0);
        paid.insert(currency, cur + cents);
        if !have || cents > best_cents || (cents == best_cents && id < best_id) {
          have = true;
          best_id = id;
          best_cents = cents;
        }
      }
    }
    let next = doc.get("next").and_then(|j| j.as_int());
    match next {
      Some(n) => { page = n; },
      None => { done = true; },
    }
  }
  let mut pj: Map<Str, Json> = Map::new();
  for k in paid.keys() {
    pj.insert(k, Json::Num(paid.get(k).unwrap_or(0)));
  }
  let mut body: Map<Str, Json> = Map::new();
  body.insert("orders", Json::Num(count));
  body.insert("paid_cents", Json::Obj(pj));
  body.insert("refunded", Json::Num(refunded));
  if have {
    body.insert("largest", Json::Num(best_id));
  } else {
    body.insert("largest", Json::Null);
  }
  let payload = Json::Obj(body).to_json().to_bytes();
  let r = match api.send("POST", "/summaries", ["content-type: application/json"], payload) {
    Ok(r) => r,
    Err(_) => return Err("post failed"),
  };
  if r.status != 201 {
    return Err("status " + r.status.to_str());
  }
  let resp = r.body.to_str().parse_json()?;
  let id = resp.get("id").and_then(|j| j.as_str()).unwrap_or("");
  Ok(id)
}

fn remove_key(xs: List<Str>, k: Str) -> List<Str> {
  let mut out: List<Str> = [];
  for x in xs {
    if x != k { out.push(x); }
  }
  out
}

fn front(xs: List<Str>, k: Str) -> List<Str> {
  let mut out: List<Str> = [k];
  for x in xs {
    if x != k { out.push(x); }
  }
  out
}

fn main(input: Dir, cache: Kv) -> Result<Str, Str> {
  let text = input.read("ops.txt").map_err(|e| "read error")?.to_str();
  let lines = text.lines();
  let mut cap = 1;
  if lines.len() > 0 {
    let c = lines[0].strip_prefix("capacity ").and_then(|s| s.trim().parse_int());
    cap = c.unwrap_or(1);
  }
  if cap < 1 { cap = 1; }

  let mut order: List<Str> = [];
  let mut vals: Map<Str, Str> = Map::new();
  let mut hits = 0;
  let mut misses = 0;
  let mut evictions = 0;

  let stored = cache.get("state").map_err(|e| "kv error")?;
  if let Some(b) = stored {
    let doc = b.to_str().parse_json()?;
    let ol: List<Json> = doc.get("order").and_then(|j| j.as_list()).unwrap_or([]);
    for j in ol {
      if let Some(s) = j.as_str() { order.push(s); }
    }
    let vm: Map<Str, Json> = doc.get("vals").and_then(|j| j.as_map()).unwrap_or(Map::new());
    for k in vm.keys() {
      let v = vm.get(k).and_then(|j| j.as_str()).unwrap_or("");
      vals.insert(k, v);
    }
    hits = doc.get("hits").and_then(|j| j.as_int()).unwrap_or(0);
    misses = doc.get("misses").and_then(|j| j.as_int()).unwrap_or(0);
    evictions = doc.get("evictions").and_then(|j| j.as_int()).unwrap_or(0);
  }

  let mut out: List<Str> = [];

  while order.len() > cap {
    if let Some(k) = order.pop() {
      vals.remove(k);
      evictions += 1;
      out.push("evict " + k);
    }
  }

  for i in 1..lines.len() {
    let line = lines[i];
    if line.trim() == "" { continue; }
    let parts = line.split(" ");
    let op = parts[0];
    if op == "get" {
      if parts.len() != 2 || parts[1] == "" {
        out.push("bad line " + (i + 1).to_str());
        continue;
      }
      let key = parts[1];
      if let Some(v) = vals.get(key) {
        hits += 1;
        order = front(order, key);
        out.push(key + "=" + v);
      } else {
        misses += 1;
        out.push(key + " miss");
      }
    } else if op == "del" {
      if parts.len() != 2 || parts[1] == "" {
        out.push("bad line " + (i + 1).to_str());
        continue;
      }
      let key = parts[1];
      if vals.get(key).is_some() {
        vals.remove(key);
        order = remove_key(order, key);
      }
    } else if op == "put" {
      let Some(rest) = line.strip_prefix("put ") else {
        out.push("bad line " + (i + 1).to_str());
        continue;
      };
      let Some(idx) = rest.find(" ") else {
        out.push("bad line " + (i + 1).to_str());
        continue;
      };
      let key = rest.slice(0, idx);
      let value = rest.slice(idx + 1, rest.len());
      if key == "" || value == "" {
        out.push("bad line " + (i + 1).to_str());
        continue;
      }
      if vals.get(key).is_none() {
        if order.len() >= cap {
          if let Some(k) = order.pop() {
            vals.remove(k);
            evictions += 1;
            out.push("evict " + k);
          }
        }
      }
      vals.insert(key, value);
      order = front(order, key);
    } else {
      out.push("bad line " + (i + 1).to_str());
    }
  }

  if order.len() == 0 {
    out.push("cache:");
  } else {
    out.push("cache: " + order.join(","));
  }
  out.push("stats hits " + hits.to_str() + " misses " + misses.to_str() + " evictions " + evictions.to_str());

  let mut ojs: List<Json> = [];
  for k in order { ojs.push(Json::Str(k)); }
  let mut vjs: Map<Str, Json> = Map::new();
  for k in vals.keys() {
    vjs.insert(k, Json::Str(vals.get(k).unwrap_or("")));
  }
  let mut st: Map<Str, Json> = Map::new();
  st.insert("order", Json::Arr(ojs));
  st.insert("vals", Json::Obj(vjs));
  st.insert("hits", Json::Num(hits));
  st.insert("misses", Json::Num(misses));
  st.insert("evictions", Json::Num(evictions));
  cache.set("state", Json::Obj(st).to_json().to_bytes()).map_err(|e| "kv error")?;

  Ok(out.join("\n"))
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("packages.json")?.to_str();
  let doc = match text.parse_json() {
    Ok(j) => j,
    Err(_) => { return Ok("error: not an object"); },
  };
  let Some(m) = doc.as_map() else { return Ok("error: not an object"); };

  let mut names: List<Str> = [];
  let mut deps: List<List<Str>> = [];
  let mut invalid: List<Str> = [];
  let mut idx: HashMap<Str, Int> = HashMap::new();
  for k in m.keys() {
    let Some(j) = m.get(k) else { continue; };
    let mut ok = true;
    let mut ds: List<Str> = [];
    let mut seen: HashMap<Str, Bool> = HashMap::new();
    match j.as_list() {
      Some(items) => {
        for it in items {
          match it.as_str() {
            Some(s) => {
              if seen.get(s).is_none() {
                seen.insert(s, true);
                ds.push(s);
              }
            }
            None => { ok = false; }
          }
        }
      }
      None => { ok = false; }
    }
    if ok {
      idx.insert(k, names.len());
      names.push(k);
      deps.push(ds);
    } else {
      invalid.push(k);
    }
  }

  let n = names.len();
  let mut adj: List<List<Int>> = [];
  let mut hasmiss: List<Bool> = [];
  let mut selfl: List<Bool> = [];
  let mut missing: Map<Str, List<Str>> = Map::new();
  for i in 0..n {
    let mut a: List<Int> = [];
    let mut hm = false;
    let mut sl = false;
    for d in deps[i] {
      match idx.get(d) {
        Some(w) => {
          a.push(w);
          if w == i { sl = true; }
        }
        None => {
          hm = true;
          let mut cur: List<Str> = missing.get(d).unwrap_or([]);
          cur.push(names[i]);
          missing.insert(d, cur);
        }
      }
    }
    adj.push(a);
    hasmiss.push(hm);
    selfl.push(sl);
  }

  // iterative Tarjan
  let mut index: List<Int> = [];
  let mut low: List<Int> = [];
  let mut onst: List<Bool> = [];
  let mut comp: List<Int> = [];
  for i in 0..n {
    index.push(-1);
    low.push(0);
    onst.push(false);
    comp.push(-1);
  }
  let mut stack: List<Int> = [];
  let mut csn: List<Int> = [];
  let mut csp: List<Int> = [];
  let mut counter = 0;
  let mut ncomp = 0;
  let mut csize: List<Int> = [];
  for s in 0..n {
    if index[s] != -1 { continue; }
    index[s] = counter;
    low[s] = counter;
    counter += 1;
    stack.push(s);
    onst[s] = true;
    csn.push(s);
    csp.push(0);
    while csn.len() > 0 {
      let top = csn.len() - 1;
      let v = csn[top];
      let p = csp[top];
      if p < adj[v].len() {
        csp[top] = p + 1;
        let w = adj[v][p];
        if index[w] == -1 {
          index[w] = counter;
          low[w] = counter;
          counter += 1;
          stack.push(w);
          onst[w] = true;
          csn.push(w);
          csp.push(0);
        } else if onst[w] {
          low[v] = low[v].min(index[w]);
        }
      } else {
        if low[v] == index[v] {
          let mut cnt = 0;
          loop {
            let Some(x) = stack.pop() else { break; };
            onst[x] = false;
            comp[x] = ncomp;
            cnt += 1;
            if x == v { break; }
          }
          csize.push(cnt);
          ncomp += 1;
        }
        csn.pop();
        csp.pop();
        if csn.len() > 0 {
          let u = csn[csn.len() - 1];
          low[u] = low[u].min(low[v]);
        }
      }
    }
  }

  let mut cyc: List<Bool> = [];
  for c in 0..ncomp { cyc.push(false); }
  for v in 0..n {
    if csize[comp[v]] >= 2 || selfl[v] { cyc[comp[v]] = true; }
  }

  let mut offs: List<Int> = [];
  let mut fillp: List<Int> = [];
  let mut run = 0;
  for c in 0..ncomp {
    offs.push(run);
    fillp.push(run);
    run += csize[c];
  }
  let mut order: List<Int> = [];
  for i in 0..n { order.push(0); }
  for i in 0..n {
    let c = comp[i];
    order[fillp[c]] = i;
    fillp[c] += 1;
  }

  let mut stage: List<Int> = [];
  let mut built: List<Bool> = [];
  for i in 0..n {
    stage.push(0);
    built.push(false);
  }
  for c in 0..ncomp {
    if cyc[c] { continue; }
    let v = order[offs[c]];
    if hasmiss[v] { continue; }
    let mut ok = true;
    let mut mx = 0;
    for w in adj[v] {
      if !built[w] {
        ok = false;
      } else if stage[w] > mx {
        mx = stage[w];
      }
    }
    if ok {
      built[v] = true;
      stage[v] = mx + 1;
    }
  }

  let mut lines: List<Str> = [];
  let mut bl: List<Int> = [];
  for v in 0..n {
    if built[v] { bl.push(v); }
  }
  let st = stage;
  bl.sort_by_key(|i| st[i]);
  let mut grp: List<Str> = [];
  let mut cs = 0;
  for v in bl {
    if st[v] != cs {
      if grp.len() > 0 {
        lines.push("stage " + cs.to_str() + ": " + grp.join(", "));
      }
      grp = [];
      cs = st[v];
    }
    grp.push(names[v]);
  }
  if grp.len() > 0 {
    lines.push("stage " + cs.to_str() + ": " + grp.join(", "));
  }

  let mut emitted: List<Bool> = [];
  for c in 0..ncomp { emitted.push(false); }
  for i in 0..n {
    let c = comp[i];
    if cyc[c] && !emitted[c] {
      emitted[c] = true;
      let mut g: List<Str> = [];
      for j in offs[c]..(offs[c] + csize[c]) {
        g.push(names[order[j]]);
      }
      lines.push("cycle: " + g.join(", "));
    }
  }

  for k in missing.keys() {
    let by: List<Str> = missing.get(k).unwrap_or([]);
    lines.push("missing: " + k + " (needed by " + by.join(", ") + ")");
  }

  if invalid.len() > 0 {
    lines.push("invalid: " + invalid.join(", "));
  }

  let mut blocked: List<Str> = [];
  for i in 0..n {
    if !built[i] && !cyc[comp[i]] { blocked.push(names[i]); }
  }
  if blocked.len() > 0 {
    lines.push("blocked: " + blocked.join(", "));
  }

  let mut bc = 0;
  for i in 0..n {
    if built[i] { bc += 1; }
  }
  lines.push("built " + bc.to_str() + " of " + n.to_str());
  Ok(lines.join("\n"))
}

struct Bk { room: Str, day: Str, s: Int, e: Int, who: Str }
struct Iv { s: Int, e: Int }
struct Cf { start: Int, text: Str }

fn tm(s: Str) -> Option<Int> {
  if s.len() != 5 { return None; }
  let b = s.to_bytes();
  if b[2] != 58 { return None; }
  for i in [0, 1, 3, 4] {
    if b[i] < 48 || b[i] > 57 { return None; }
  }
  let h = (b[0] - 48) * 10 + (b[1] - 48);
  let m = (b[3] - 48) * 10 + (b[4] - 48);
  if m > 59 { return None; }
  if h > 23 {
    if h == 24 && m == 0 { return Some(1440); }
    return None;
  }
  Some(h * 60 + m)
}

fn p2(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn tstr(m: Int) -> Str {
  p2(m / 60) + ":" + p2(m % 60)
}

fn rng(a: Int, b: Int) -> Str {
  tstr(a) + "-" + tstr(b)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("bookings.csv")?.to_str();
  let lines = text.lines();
  let mut skipped: List<Str> = [];
  let mut bks: List<Bk> = [];
  let mut seen: HashMap<Str, Bool> = HashMap::new();
  for i in 1..lines.len() {
    let line = lines[i];
    let n = i + 1;
    if line.trim() == "" { continue; }
    let f = line.split(",");
    if f.len() != 5 { skipped.push(n.to_str()); continue; }
    let Some(s) = tm(f[2]) else { skipped.push(n.to_str()); continue; };
    let Some(e) = tm(f[3]) else { skipped.push(n.to_str()); continue; };
    if e <= s { skipped.push(n.to_str()); continue; }
    if seen.get(line).is_some() { continue; }
    seen.insert(line, true);
    bks.push(Bk { room: f[0], day: f[1], s: s, e: e, who: f[4] });
  }
  bks.sort_by(|a: Bk, b: Bk| {
    if a.room != b.room { a.room < b.room } else { a.day < b.day }
  });
  let mut out: List<Str> = [];
  let mut gi = 0;
  while gi < bks.len() {
    let mut gj = gi;
    while gj < bks.len() && bks[gj].room == bks[gi].room && bks[gj].day == bks[gi].day {
      gj += 1;
    }
    let mut g = bks.slice(gi, gj);
    out.push(bks[gi].room + " " + bks[gi].day);
    g.sort_by_key(|b: Bk| b.s);
    let mut merged: List<Iv> = [];
    for b in g {
      let k = merged.len();
      if k > 0 && b.s <= merged[k - 1].e {
        if b.e > merged[k - 1].e { merged[k - 1].e = b.e; }
      } else {
        merged.push(Iv { s: b.s, e: b.e });
      }
    }
    let mut busy: List<Str> = [];
    let mut free: List<Str> = [];
    let mut pos = 540;
    for iv in merged {
      busy.push(rng(iv.s, iv.e));
      let ge = iv.s.min(1080);
      if ge - pos >= 30 { free.push(rng(pos, ge)); }
      pos = pos.max(iv.e);
    }
    if 1080 - pos >= 30 { free.push(rng(pos, 1080)); }
    out.push("  busy " + busy.join(", "));
    if free.len() == 0 {
      out.push("  free none");
    } else {
      out.push("  free " + free.join(", "));
    }
    let mut cfs: List<Cf> = [];
    for i in 0..g.len() {
      for j in (i + 1)..g.len() {
        let lo = g[i].s.max(g[j].s);
        let hi = g[i].e.min(g[j].e);
        if hi > lo {
          let mut a = g[i].who;
          let mut b = g[j].who;
          if b < a {
            let t = a;
            a = b;
            b = t;
          }
          cfs.push(Cf { start: lo, text: "  conflict " + a + "/" + b + " " + rng(lo, hi) });
        }
      }
    }
    cfs.sort_by(|a: Cf, b: Cf| {
      if a.start != b.start { a.start < b.start } else { a.text < b.text }
    });
    for c in cfs { out.push(c.text); }
    gi = gj;
  }
  if skipped.len() == 0 {
    out.push("skipped: none");
  } else {
    out.push("skipped: " + skipped.join(", "));
  }
  Ok(out.join("\n") + "\n")
}

struct VErr { path: Str, msg: Str }

fn less(a: VErr, b: VErr) -> Bool {
  if a.path == b.path { a.msg < b.msg } else { a.path < b.path }
}

fn type_ok(t: Str, v: Json) -> Bool {
  if t == "object" { return v.as_map().is_some(); }
  if t == "array" { return v.as_list().is_some(); }
  if t == "string" { return v.as_str().is_some(); }
  if t == "boolean" { return v.as_bool().is_some(); }
  if t == "integer" {
    return match v { Json::Num(_) => true, _ => false };
  }
  if t == "number" {
    return match v { Json::Num(_) => true, Json::Float(_) => true, _ => false };
  }
  if t == "null" {
    return match v { Json::Null => true, _ => false };
  }
  false
}

fn below(v: Json, m: Int) -> Bool {
  match v { Json::Num(n) => n < m, Json::Float(f) => f < m.to_float(), _ => false }
}

fn above(v: Json, m: Int) -> Bool {
  match v { Json::Num(n) => n > m, Json::Float(f) => f > m.to_float(), _ => false }
}

fn validate(schema: Json, v: Json, path: Str, errs: List<VErr>) -> List<VErr> {
  let t = schema.get("type").and_then(|j| j.as_str()).unwrap_or("");
  let mut out = errs;
  if !type_ok(t, v) {
    out.push(VErr { path: path, msg: "expected " + t });
    return out;
  }
  if t == "object" {
    let Some(m) = v.as_map() else { return out; };
    let no_list: List<Json> = [];
    let no_map: Map<Str, Json> = Map::new();
    let req = schema.get("required").and_then(|j| j.as_list()).unwrap_or(no_list);
    for r in req {
      let Some(name) = r.as_str() else { continue; };
      if m.get(name).is_none() {
        out.push(VErr { path: path + "." + name, msg: "missing required field" });
      }
    }
    let props = schema.get("properties").and_then(|j| j.as_map()).unwrap_or(no_map);
    for k in props.keys() {
      let Some(c) = m.get(k) else { continue; };
      let Some(sub) = props.get(k) else { continue; };
      out = validate(sub, c, path + "." + k, out);
    }
    let add = schema.get("additional").and_then(|j| j.as_bool());
    if add == Some(false) {
      for k in m.keys() {
        if props.get(k).is_none() {
          out.push(VErr { path: path + "." + k, msg: "unexpected field" });
        }
      }
    }
  } else if t == "array" {
    let Some(items) = v.as_list() else { return out; };
    if let Some(n) = schema.get("min_items").and_then(|j| j.as_int()) {
      if items.len() < n {
        out.push(VErr { path: path, msg: "fewer than " + n.to_str() + " items" });
      }
    }
    if let Some(sub) = schema.get("items") {
      let mut i = 0;
      for e in items {
        out = validate(sub, e, path + "[" + i.to_str() + "]", out);
        i += 1;
      }
    }
  } else if t == "string" {
    let s = v.as_str().unwrap_or("");
    let n = s.chars().len();
    let mut msg: Option<Str> = None;
    if let Some(mn) = schema.get("min_length").and_then(|j| j.as_int()) {
      if n < mn { msg = Some("shorter than " + mn.to_str()); }
    }
    if msg.is_none() {
      if let Some(mx) = schema.get("max_length").and_then(|j| j.as_int()) {
        if n > mx { msg = Some("longer than " + mx.to_str()); }
      }
    }
    if msg.is_none() {
      if let Some(en) = schema.get("enum").and_then(|j| j.as_list()) {
        let mut found = false;
        for e in en {
          if e.as_str() == Some(s) { found = true; }
        }
        if !found { msg = Some("not in enum"); }
      }
    }
    if let Some(m) = msg {
      out.push(VErr { path: path, msg: m });
    }
  } else if t == "integer" || t == "number" {
    let mut msg: Option<Str> = None;
    if let Some(mn) = schema.get("minimum").and_then(|j| j.as_int()) {
      if below(v, mn) { msg = Some("less than " + mn.to_str()); }
    }
    if msg.is_none() {
      if let Some(mx) = schema.get("maximum").and_then(|j| j.as_int()) {
        if above(v, mx) { msg = Some("greater than " + mx.to_str()); }
      }
    }
    if let Some(m) = msg {
      out.push(VErr { path: path, msg: m });
    }
  }
  out
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let schema_text = input.read("schema.json")?.to_str();
  let schema = match schema_text.parse_json() {
    Ok(j) => j,
    Err(e) => { return Ok("invalid schema: " + e); },
  };
  let text = input.read("records.jsonl")?.to_str();
  let mut out: List<Str> = [];
  let mut n = 0;
  let mut valid = 0;
  let mut total = 0;
  for line in text.lines() {
    n += 1;
    if line.trim() == "" { continue; }
    total += 1;
    match line.parse_json() {
      Err(_) => { out.push("line " + n.to_str() + ": invalid JSON"); },
      Ok(v) => {
        let start: List<VErr> = [];
        let mut errs = validate(schema, v, "$", start);
        if errs.len() == 0 {
          valid += 1;
          out.push("line " + n.to_str() + ": ok");
        } else {
          errs.sort_by(less);
          for e in errs {
            out.push("line " + n.to_str() + ": " + e.path + ": " + e.msg);
          }
        }
      },
    }
  }
  out.push("valid " + valid.to_str() + " of " + total.to_str());
  Ok(out.join("\n"))
}

fn push(api: Http, id: Str, body: Bytes) -> Str {
  let mut attempt = 0;
  while attempt < 3 {
    attempt += 1;
    match api.send("PUT", "/records/" + id, ["content-type: application/json"], body) {
      Ok(r) => {
        if r.status >= 200 && r.status < 300 { return "synced"; }
        if r.status >= 400 && r.status < 500 { return "rejected " + r.status.to_str(); }
      }
      Err(_) => {}
    }
  }
  "failed"
}

fn main(input: Dir, state: Kv, api: Http) -> Result<Str, Str> {
  let text = input.read("records.jsonl").map_err(|e| "read failed")?.to_str();
  let mut out = "";
  let mut bodies: Map<Str, Str> = Map::new();
  let mut versions: Map<Str, Int> = Map::new();
  let mut n = 0;
  for line in text.lines() {
    n = n + 1;
    let t = line.trim();
    if t.len() == 0 { continue; }
    let invalid = "line " + n.to_str() + " invalid\n";
    let Ok(j) = t.parse_json() else { out = out + invalid; continue; };
    let Some(_o) = j.as_map() else { out = out + invalid; continue; };
    let Some(id) = j.get("id").and_then(|x| x.as_str()) else { out = out + invalid; continue; };
    let Some(ver) = j.get("version").and_then(|x| x.as_int()) else { out = out + invalid; continue; };
    bodies.insert(id, t);
    versions.insert(id, ver);
  }
  let mut synced = 0;
  let mut unchanged = 0;
  let mut rejected = 0;
  let mut failed = 0;
  for id in bodies.keys() {
    let ver = versions.get(id).unwrap_or(0);
    let key = "v/" + id;
    let stored = state.get(key).map_err(|e| "kv failed")?;
    let last: Option<Int> = match stored {
      Some(b) => b.to_str().parse_int(),
      None => None,
    };
    let mut skip = false;
    if let Some(p) = last {
      if ver <= p { skip = true; }
    }
    if skip {
      unchanged = unchanged + 1;
      out = out + id + " unchanged\n";
      continue;
    }
    let body = bodies.get(id).unwrap_or("");
    let res = push(api, id, body.to_bytes());
    if res == "synced" {
      state.set(key, ver.to_str().to_bytes()).map_err(|e| "kv failed")?;
      synced = synced + 1;
    } else if res == "failed" {
      failed = failed + 1;
    } else {
      rejected = rejected + 1;
    }
    out = out + id + " " + res + "\n";
  }
  out = out + "synced " + synced.to_str() + " unchanged " + unchanged.to_str() + " rejected " + rejected.to_str() + " failed " + failed.to_str();
  Ok(out)
}

enum Outcome { Done, Dup, Fail(Str) }

fn fail(m: Str) -> Result<Outcome, Str> {
  Ok(Outcome::Fail(m))
}

fn pad(n: Int, w: Int) -> Str {
  let mut s = n.to_str();
  while s.len() < w { s = "0" + s; }
  s
}

fn fmt(ms: Int) -> Str {
  let secs = ms / 1000;
  let days = secs / 86400;
  let rem = secs % 86400;
  let h = rem / 3600;
  let mi = (rem % 3600) / 60;
  let s = rem % 60;
  let z = days + 719468;
  let era = z / 146097;
  let doe = z - era * 146097;
  let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
  let y0 = yoe + era * 400;
  let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
  let mp = (5 * doy + 2) / 153;
  let d = doy - (153 * mp + 2) / 5 + 1;
  let m = if mp < 10 { mp + 3 } else { mp - 9 };
  let y = if m <= 2 { y0 + 1 } else { y0 };
  pad(y, 4) + "-" + pad(m, 2) + "-" + pad(d, 2) + "T" + pad(h, 2) + ":" + pad(mi, 2) + ":" + pad(s, 2) + "Z"
}

fn bal(db: Db, name: Str) -> Result<Option<Int>, Str> {
  let rows = db.query("SELECT balance FROM accounts WHERE name = ? AND closed = 0", [SqlValue::Text(name)]).map_err(|e| "db error")?;
  if rows.len() == 0 { return Ok(None); }
  match rows[0][0] {
    SqlValue::Int(n) => Ok(Some(n)),
    _ => Ok(None),
  }
}

fn ever(db: Db, name: Str) -> Result<Bool, Str> {
  let rows = db.query("SELECT 1 FROM accounts WHERE name = ?", [SqlValue::Text(name)]).map_err(|e| "db error")?;
  Ok(rows.len() > 0)
}

fn apply(db: Db, line: Str, now: Int) -> Result<Outcome, Str> {
  let w = line.split(" ");
  let op = w[0];
  if op == "open" {
    if w.len() != 3 { return fail("malformed"); }
    let Some(c) = w[2].parse_int() else { return fail("malformed"); };
    if c < 0 { return fail("bad amount"); }
    if ever(db, w[1])? { return fail("account exists"); }
    db.exec("INSERT INTO accounts (name, balance, closed, last_ms) VALUES (?, ?, 0, ?)", [SqlValue::Text(w[1]), SqlValue::Int(c), SqlValue::Int(now)]).map_err(|e| "db error")?;
    return Ok(Outcome::Done);
  }
  if op == "close" {
    if w.len() != 2 { return fail("malformed"); }
    let Some(b) = bal(db, w[1])? else { return fail("no account " + w[1]); };
    if b != 0 { return fail("balance not zero"); }
    db.exec("UPDATE accounts SET closed = 1, last_ms = ? WHERE name = ?", [SqlValue::Int(now), SqlValue::Text(w[1])]).map_err(|e| "db error")?;
    return Ok(Outcome::Done);
  }
  if op == "transfer" {
    if w.len() != 5 { return fail("malformed"); }
    let Some(c) = w[4].parse_int() else { return fail("malformed"); };
    let id = w[1];
    let from = w[2];
    let to = w[3];
    let rows = db.query("SELECT src, dst, cents FROM transfers WHERE id = ?", [SqlValue::Text(id)]).map_err(|e| "db error")?;
    if rows.len() > 0 {
      if rows[0][0] == SqlValue::Text(from) && rows[0][1] == SqlValue::Text(to) && rows[0][2] == SqlValue::Int(c) {
        return Ok(Outcome::Dup);
      }
      return fail("id reused");
    }
    if c <= 0 { return fail("bad amount"); }
    if from == to { return fail("same account"); }
    let Some(fb) = bal(db, from)? else { return fail("no account " + from); };
    let Some(tb) = bal(db, to)? else { return fail("no account " + to); };
    if fb < c { return fail("insufficient funds"); }
    if tb > 9223372036854775807 - c { return fail("overflow"); }
    let stmts = [
      "UPDATE accounts SET balance = balance - ?, last_ms = ? WHERE name = ?",
      "UPDATE accounts SET balance = balance + ?, last_ms = ? WHERE name = ?",
      "INSERT INTO transfers (id, src, dst, cents) VALUES (?, ?, ?, ?)"
    ];
    let params = [
      [SqlValue::Int(c), SqlValue::Int(now), SqlValue::Text(from)],
      [SqlValue::Int(c), SqlValue::Int(now), SqlValue::Text(to)],
      [SqlValue::Text(id), SqlValue::Text(from), SqlValue::Text(to), SqlValue::Int(c)]
    ];
    db.transaction(stmts, params).map_err(|e| "db error")?;
    return Ok(Outcome::Done);
  }
  fail("malformed")
}

fn main(input: Dir, db: Db, log: Log, clock: Clock) -> Result<Str, Str> {
  let now = clock.now_ms();
  let stamp = fmt(now);
  db.exec("CREATE TABLE IF NOT EXISTS accounts (name TEXT PRIMARY KEY, balance INTEGER NOT NULL, closed INTEGER NOT NULL, last_ms INTEGER NOT NULL)", []).map_err(|e| "db error")?;
  db.exec("CREATE TABLE IF NOT EXISTS transfers (id TEXT PRIMARY KEY, src TEXT NOT NULL, dst TEXT NOT NULL, cents INTEGER NOT NULL)", []).map_err(|e| "db error")?;
  let text = input.read("ops.txt").map_err(|e| "read error")?.to_str();
  let lines = text.lines();
  let mut ok = 0;
  let mut failed = 0;
  let mut dup = 0;
  for i in 0..lines.len() {
    let line = lines[i];
    if line.trim() == "" { continue; }
    let r = apply(db, line, now)?;
    match r {
      Outcome::Done => { ok += 1; }
      Outcome::Dup => { dup += 1; }
      Outcome::Fail(m) => {
        failed += 1;
        log.write(stamp + " line " + (i + 1).to_str() + ": " + m).map_err(|e| "log error")?;
      }
    }
  }
  let mut out = "ok " + ok.to_str() + " failed " + failed.to_str() + " duplicate " + dup.to_str();
  let rows = db.query("SELECT name, balance, last_ms FROM accounts WHERE closed = 0 ORDER BY name", []).map_err(|e| "db error")?;
  for row in rows {
    let name = match row[0] { SqlValue::Text(s) => s, _ => "" };
    let b = match row[1] { SqlValue::Int(n) => n, _ => 0 };
    let t = match row[2] { SqlValue::Int(n) => n, _ => 0 };
    out = out + "\n" + name + " " + b.to_str() + " last " + fmt(t);
  }
  Ok(out)
}

struct Reply { status: Int, body: Str }
struct Cred { name: Str, password: Str }
struct Sess { name: Str, token: Str }

fn err(status: Int, msg: Str) -> Reply {
  Reply { status: status, body: "{\"error\":\"" + msg + "\"}" }
}

fn kget(store: Kv, k: Str) -> Option<Str> {
  match store.get(k) {
    Ok(Some(b)) => Some(b.to_str()),
    _ => None,
  }
}

fn kset(store: Kv, k: Str, v: Str) {
  let r = store.set(k, v.to_bytes());
}

fn valid_name(n: Str) -> Bool {
  let l = n.len();
  if l < 3 || l > 20 { return false; }
  for b in n.to_bytes() {
    let ok = (b >= 97 && b <= 122) || (b >= 48 && b <= 57) || b == 95;
    if !ok { return false; }
  }
  true
}

fn hash(name: Str, pw: Str) -> Str {
  (name + ":" + pw).sha256().to_hex()
}

fn creds(body: Bytes) -> Option<Cred> {
  let doc = body.to_str().parse_json().ok()?;
  let name = doc.get("name").and_then(|j| j.as_str())?;
  let password = doc.get("password").and_then(|j| j.as_str())?;
  Some(Cred { name: name, password: password })
}

fn create_user(store: Kv, body: Bytes) -> Reply {
  let Some(c) = creds(body) else { return err(400, "invalid"); };
  if !valid_name(c.name) || c.password.len() < 8 { return err(400, "invalid"); }
  let h: Option<Bytes> = Some(hash(c.name, c.password).to_bytes());
  match store.swap("user:" + c.name, None, h) {
    Ok(true) => Reply { status: 201, body: "{\"name\":\"" + c.name + "\"}" },
    Ok(false) => err(409, "name taken"),
    Err(_) => err(500, "internal"),
  }
}

fn login(store: Kv, clock: Clock, rng: Rng, body: Bytes) -> Reply {
  let Some(c) = creds(body) else { return err(401, "bad credentials"); };
  let Some(stored) = kget(store, "user:" + c.name) else { return err(401, "bad credentials"); };
  let now = clock.now_ms();
  let until = kget(store, "lock:" + c.name).and_then(|s| s.parse_int()).unwrap_or(0);
  if now < until { return err(429, "locked"); }
  if hash(c.name, c.password).ct_eq(stored) {
    kset(store, "fails:" + c.name, "0");
    let a = store.add("logins:" + c.name, 1);
    let token = rng.bytes(16).to_hex();
    kset(store, "sess:" + token, c.name + "," + (now + 1800000).to_str());
    Reply { status: 200, body: "{\"token\":\"" + token + "\",\"expires_in\":1800}" }
  } else {
    match store.add("fails:" + c.name, 1) {
      Ok(n) => {
        if n >= 3 {
          kset(store, "lock:" + c.name, (now + 900000).to_str());
          kset(store, "fails:" + c.name, "0");
        }
      },
      Err(_) => {},
    }
    err(401, "bad credentials")
  }
}

fn bearer(req: Incoming) -> Option<Str> {
  let names = req.header_names();
  let vals = req.header_values();
  let mut i = 0;
  while i < names.len() {
    if names[i] == "authorization" { return vals[i].strip_prefix("Bearer "); }
    i += 1;
  }
  None
}

fn session(store: Kv, clock: Clock, req: Incoming) -> Option<Sess> {
  let tok = bearer(req)?;
  let v = kget(store, "sess:" + tok)?;
  let parts = v.split(",");
  if parts.len() != 2 { return None; }
  let exp = parts[1].parse_int()?;
  if clock.now_ms() >= exp { return None; }
  Some(Sess { name: parts[0], token: tok })
}

fn me(store: Kv, clock: Clock, req: Incoming) -> Reply {
  let Some(s) = session(store, clock, req) else { return err(401, "unauthorized"); };
  kset(store, "sess:" + s.token, s.name + "," + (clock.now_ms() + 1800000).to_str());
  let n = kget(store, "logins:" + s.name).and_then(|x| x.parse_int()).unwrap_or(0);
  Reply { status: 200, body: "{\"name\":\"" + s.name + "\",\"logins\":" + n.to_str() + "}" }
}

fn logout(store: Kv, clock: Clock, req: Incoming) -> Reply {
  let Some(s) = session(store, clock, req) else { return err(401, "unauthorized"); };
  let r = store.delete("sess:" + s.token);
  Reply { status: 204, body: "" }
}

fn route(req: Incoming, store: Kv, clock: Clock, rng: Rng) -> Reply {
  let m = req.method();
  let path = req.target().split("?")[0];
  if m == "POST" && path == "/users" { return create_user(store, req.body()); }
  if m == "POST" && path == "/login" { return login(store, clock, rng, req.body()); }
  if m == "GET" && path == "/me" { return me(store, clock, req); }
  if m == "POST" && path == "/logout" { return logout(store, clock, req); }
  err(404, "not found")
}

fn main(req: Incoming, res: Outgoing, store: Kv, clock: Clock, rng: Rng) -> Str {
  let r = route(req, store, clock, rng);
  if r.status == 204 {
    let x = res.send(204, [], [], "".to_bytes());
  } else {
    let x = res.send(r.status, ["content-type"], ["application/json"], r.body.to_bytes());
  }
  ""
}

struct Resp { status: Int, body: Str }

fn err(status: Int, msg: Str) -> Resp {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Resp { status: status, body: Json::Obj(m).to_json() }
}

fn sv_int(v: SqlValue) -> Int {
  match v { SqlValue::Int(i) => i, _ => 0 }
}

fn sv_text(v: SqlValue) -> Str {
  match v { SqlValue::Text(s) => s, _ => "" }
}

fn pay_json(p: List<SqlValue>) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Str("pay_" + sv_int(p[0]).to_str()));
  m.insert("account", Json::Str(sv_text(p[1])));
  m.insert("cents", Json::Num(sv_int(p[2])));
  m.insert("currency", Json::Str(sv_text(p[3])));
  m.insert("status", Json::Str(sv_text(p[4])));
  m.insert("refunded", Json::Num(sv_int(p[5])));
  Json::Obj(m)
}

fn ok_pay(status: Int, p: List<SqlValue>) -> Resp {
  Resp { status: status, body: pay_json(p).to_json() }
}

fn hexv(b: Int) -> Int {
  if b >= 48 && b <= 57 { b - 48 }
  else if b >= 97 && b <= 102 { b - 87 }
  else if b >= 65 && b <= 70 { b - 55 }
  else { -1 }
}

fn decode(s: Str) -> Str {
  let b = s.to_bytes();
  let mut out = "".to_bytes();
  let mut i = 0;
  while i < b.len() {
    let c = b[i];
    if c == 43 {
      out.push(32);
      i += 1;
    } else if c == 37 && i + 2 < b.len() {
      let h = hexv(b[i + 1]);
      let l = hexv(b[i + 2]);
      if h >= 0 && l >= 0 {
        out.push(h * 16 + l);
        i += 3;
      } else {
        out.push(c);
        i += 1;
      }
    } else {
      out.push(c);
      i += 1;
    }
  }
  out.to_str()
}

fn find_header(req: Incoming, name: Str) -> Option<Str> {
  let names = req.header_names();
  let vals = req.header_values();
  let mut i = 0;
  while i < names.len() {
    if names[i] == name { return Some(vals[i].trim()); }
    i += 1;
  }
  None
}

fn get_payment(db: Db, id: Str) -> Result<Option<List<SqlValue>>, DbErr> {
  let Some(d) = id.strip_prefix("pay_") else { return Ok(None); };
  let Some(n) = d.parse_int() else { return Ok(None); };
  if n < 1 || n.to_str() != d { return Ok(None); }
  let rows = db.query("SELECT n, account, cents, currency, status, refunded FROM payments WHERE n = ?", [SqlValue::Int(n)])?;
  if rows.len() == 0 { Ok(None) } else { Ok(Some(rows[0])) }
}

fn do_create(db: Db, body: Str) -> Result<Resp, DbErr> {
  let invalid = err(422, "invalid payment");
  let Ok(j) = body.parse_json() else { return Ok(invalid); };
  let Some(m) = j.as_map() else { return Ok(invalid); };
  if m.len() != 3 { return Ok(invalid); }
  let Some(account) = m.get("account").and_then(|x| x.as_str()) else { return Ok(invalid); };
  let Some(cents) = m.get("cents").and_then(|x| x.as_int()) else { return Ok(invalid); };
  let Some(currency) = m.get("currency").and_then(|x| x.as_str()) else { return Ok(invalid); };
  if account.len() == 0 || cents <= 0 { return Ok(invalid); }
  if currency != "EUR" && currency != "USD" { return Ok(invalid); }
  let rows = db.query("INSERT INTO payments(account, cents, currency, status, refunded) VALUES (?, ?, ?, 'pending', 0) RETURNING n, account, cents, currency, status, refunded",
    [SqlValue::Text(account), SqlValue::Int(cents), SqlValue::Text(currency)])?;
  if rows.len() == 0 { return Ok(err(500, "internal error")); }
  Ok(ok_pay(201, rows[0]))
}

fn transition(db: Db, id: Str, from: Str, to: Str, same_ok: Bool) -> Result<Resp, DbErr> {
  let Some(p) = get_payment(db, id)? else { return Ok(err(404, "not found")); };
  let st = sv_text(p[4]);
  if st == to && same_ok { return Ok(ok_pay(200, p)); }
  if st != from { return Ok(err(409, "invalid transition")); }
  let n = sv_int(p[0]);
  db.exec("UPDATE payments SET status = ? WHERE n = ? AND status = ?",
    [SqlValue::Text(to), SqlValue::Int(n), SqlValue::Text(from)])?;
  let Some(p2) = get_payment(db, id)? else { return Ok(err(404, "not found")); };
  if sv_text(p2[4]) == to { Ok(ok_pay(200, p2)) } else { Ok(err(409, "invalid transition")) }
}

fn do_refund(db: Db, id: Str, body: Str) -> Result<Resp, DbErr> {
  let Some(p) = get_payment(db, id)? else { return Ok(err(404, "not found")); };
  let invalid = err(422, "invalid refund");
  let Ok(j) = body.parse_json() else { return Ok(invalid); };
  let Some(amt) = j.get("cents").and_then(|x| x.as_int()) else { return Ok(invalid); };
  if amt <= 0 { return Ok(invalid); }
  if sv_text(p[4]) != "captured" { return Ok(err(409, "invalid transition")); }
  let cents = sv_int(p[2]);
  let refunded = sv_int(p[5]);
  if amt > cents - refunded { return Ok(err(409, "exceeds captured")); }
  let n = sv_int(p[0]);
  let changed = db.exec("UPDATE payments SET refunded = refunded + ?, status = CASE WHEN refunded + ? = cents THEN 'refunded' ELSE status END WHERE n = ? AND status = 'captured' AND refunded + ? <= cents",
    [SqlValue::Int(amt), SqlValue::Int(amt), SqlValue::Int(n), SqlValue::Int(amt)])?;
  if changed == 0 { return Ok(err(409, "invalid transition")); }
  let Some(p2) = get_payment(db, id)? else { return Ok(err(404, "not found")); };
  Ok(ok_pay(200, p2))
}

fn canon(text: Str) -> Str {
  match text.parse_json() {
    Ok(j) => j.to_json(),
    Err(_) => text,
  }
}

fn idem(req: Incoming, db: Db, path: Str, id: Str, create: Bool) -> Result<Resp, DbErr> {
  let key = match find_header(req, "idempotency-key") {
    Some(k) => k,
    None => return Ok(err(400, "missing idempotency key")),
  };
  if key.len() == 0 { return Ok(err(400, "missing idempotency key")); }
  let text = req.body().to_str();
  let c = canon(text);
  let rows = db.query("SELECT method, path, body, status, resp FROM idem WHERE key = ?", [SqlValue::Text(key)])?;
  if rows.len() > 0 {
    let r = rows[0];
    if sv_text(r[0]) == "POST" && sv_text(r[1]) == path && sv_text(r[2]) == c {
      return Ok(Resp { status: sv_int(r[3]), body: sv_text(r[4]) });
    }
    return Ok(err(409, "key reused"));
  }
  let r = if create { do_create(db, text)? } else { do_refund(db, id, text)? };
  if r.status >= 200 && r.status < 300 {
    db.exec("INSERT OR IGNORE INTO idem(key, method, path, body, status, resp) VALUES (?, ?, ?, ?, ?, ?)",
      [SqlValue::Text(key), SqlValue::Text("POST"), SqlValue::Text(path), SqlValue::Text(c), SqlValue::Int(r.status), SqlValue::Text(r.body)])?;
  }
  Ok(r)
}

fn list_payments(db: Db, query: Str) -> Result<Resp, DbErr> {
  let mut account: Option<Str> = None;
  for part in query.split("&") {
    if let Some(v) = part.strip_prefix("account=") {
      account = Some(decode(v));
      break;
    }
  }
  let rows = match account {
    Some(a) => db.query("SELECT n, account, cents, currency, status, refunded FROM payments WHERE account = ? ORDER BY n", [SqlValue::Text(a)])?,
    None => db.query("SELECT n, account, cents, currency, status, refunded FROM payments ORDER BY n", [])?,
  };
  let mut items: List<Json> = [];
  for r in rows { items.push(pay_json(r)); }
  Ok(Resp { status: 200, body: Json::Arr(items).to_json() })
}

fn route(req: Incoming, db: Db) -> Result<Resp, DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS payments (n INTEGER PRIMARY KEY AUTOINCREMENT, account TEXT NOT NULL, cents INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, refunded INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS idem (key TEXT PRIMARY KEY, method TEXT NOT NULL, path TEXT NOT NULL, body TEXT NOT NULL, status INTEGER NOT NULL, resp TEXT NOT NULL)", [])?;
  let method = req.method();
  let target = req.target();
  let mut path = target;
  let mut query = "";
  if let Some(i) = target.find("?") {
    path = target.slice(0, i);
    query = target.slice(i + 1, target.len());
  }
  let segs = path.split("/");
  if segs.len() < 2 || segs[0] != "" || segs[1] != "payments" {
    return Ok(err(404, "not found"));
  }
  let n = segs.len();
  if n == 2 {
    if method == "POST" { return idem(req, db, path, "", true); }
    if method == "GET" { return list_payments(db, query); }
  } else if n == 3 {
    if method == "GET" {
      let Some(p) = get_payment(db, segs[2])? else { return Ok(err(404, "not found")); };
      return Ok(ok_pay(200, p));
    }
  } else if n == 4 && method == "POST" {
    if segs[3] == "capture" { return transition(db, segs[2], "pending", "captured", true); }
    if segs[3] == "cancel" { return transition(db, segs[2], "pending", "canceled", false); }
    if segs[3] == "refund" { return idem(req, db, path, segs[2], false); }
  }
  Ok(err(404, "not found"))
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Result<Str, WebErr> {
  let r = match route(req, db) {
    Ok(x) => x,
    Err(_) => err(500, "internal error"),
  };
  res.send(r.status, ["content-type"], ["application/json"], r.body.to_bytes())?;
  Ok(r.body)
}

fn digits(b: Bytes, from: Int, to: Int) -> Bool {
  let mut i = from;
  while i < to {
    if b[i] < 48 || b[i] > 57 { return false; }
    i += 1;
  }
  true
}

fn num(b: Bytes, from: Int, to: Int) -> Int {
  let mut v = 0;
  let mut i = from;
  while i < to {
    v = v * 10 + b[i] - 48;
    i += 1;
  }
  v
}

fn is_leap(y: Int) -> Bool {
  y % 4 == 0 && (y % 100 != 0 || y % 400 == 0)
}

fn dim(y: Int, m: Int) -> Int {
  match m {
    2 => if is_leap(y) { 29 } else { 28 },
    4 | 6 | 9 | 11 => 30,
    _ => 31,
  }
}

fn parse_time(s: Str) -> Option<Int> {
  let b = s.to_bytes();
  if b.len() != 20 { return None; }
  if b[4] != 45 || b[7] != 45 || b[10] != 84 || b[13] != 58 || b[16] != 58 || b[19] != 90 {
    return None;
  }
  if !digits(b, 0, 4) || !digits(b, 5, 7) || !digits(b, 8, 10) || !digits(b, 11, 13) || !digits(b, 14, 16) || !digits(b, 17, 19) {
    return None;
  }
  let y = num(b, 0, 4);
  let mo = num(b, 5, 7);
  let d = num(b, 8, 10);
  let h = num(b, 11, 13);
  let mi = num(b, 14, 16);
  let se = num(b, 17, 19);
  if mo < 1 || mo > 12 { return None; }
  if d < 1 || d > dim(y, mo) { return None; }
  if h > 23 || mi > 59 || se > 59 { return None; }
  let yy = y + 400 - 1;
  let mut days = yy * 365 + yy / 4 - yy / 100 + yy / 400;
  let mut m = 1;
  while m < mo {
    days += dim(y, m);
    m += 1;
  }
  days += d;
  Some(days * 86400 + h * 3600 + mi * 60 + se)
}

fn pad2(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn hms(s: Int) -> Str {
  pad2(s / 3600) + ":" + pad2((s % 3600) / 60) + ":" + pad2(s % 60)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("events.log")?.to_str();
  let mut seen: HashMap<Str, Bool> = HashMap::new();
  let mut users: Map<Str, List<Int>> = Map::new();
  let mut upages: HashMap<Str, HashMap<Str, Bool>> = HashMap::new();
  let mut counts: HashMap<Str, Int> = HashMap::new();
  let mut malformed = 0;
  let mut dups = 0;
  for line in text.lines() {
    if line.trim() == "" { continue; }
    if seen.get(line).is_some() {
      dups += 1;
      continue;
    }
    seen.insert(line, true);
    let parts = line.split(" ");
    if parts.len() != 3 {
      malformed += 1;
      continue;
    }
    let Some(t) = parse_time(parts[0]) else {
      malformed += 1;
      continue;
    };
    let user = parts[1];
    let page = parts[2];
    let mut ts: List<Int> = users.get(user).unwrap_or([]);
    ts.push(t);
    users.insert(user, ts);
    let mut pg: HashMap<Str, Bool> = upages.get(user).unwrap_or(HashMap::new());
    pg.insert(page, true);
    upages.insert(user, pg);
    counts.insert(page, counts.get(page).unwrap_or(0) + 1);
  }
  let mut out: List<Str> = [];
  let mut durs: List<Int> = [];
  for u in users.keys() {
    let mut ts: List<Int> = users.get(u).unwrap_or([]);
    ts.sort();
    let n = ts.len();
    let mut start = ts[0];
    let mut prev = ts[0];
    let mut sessions = 1;
    let mut longest = 0;
    for i in 1..n {
      let t = ts[i];
      if t - prev > 1800 {
        let dur = prev - start;
        durs.push(dur);
        longest = longest.max(dur);
        sessions += 1;
        start = t;
      }
      prev = t;
    }
    let dur = prev - start;
    durs.push(dur);
    longest = longest.max(dur);
    let np = upages.get(u).unwrap_or(HashMap::new()).len();
    out.push(u + " sessions " + sessions.to_str() + " events " + n.to_str() + " longest " + hms(longest) + " pages " + np.to_str());
  }
  if durs.len() > 0 {
    durs.sort();
    out.push("median " + durs[(durs.len() - 1) / 2].to_str());
    let mut pages = counts.keys();
    let c = counts;
    pages.sort_by(|a, b| {
      let ca = c.get(a).unwrap_or(0);
      let cb = c.get(b).unwrap_or(0);
      if ca != cb { ca > cb } else { a < b }
    });
    let mut tops: List<Str> = [];
    let mut i = 0;
    while i < 3 && i < pages.len() {
      tops.push(pages[i] + " (" + c.get(pages[i]).unwrap_or(0).to_str() + ")");
      i += 1;
    }
    out.push("top: " + tops.join(", "));
  }
  out.push("malformed " + malformed.to_str() + " duplicates " + dups.to_str());
  Ok(out.join("\n"))
}

struct Rec { fields: List<Str>, bad: Bool }
struct Price { cents: Int, text: Str }
struct Agg { rev: Int, items: Int, prods: Map<Str, Int> }

fn parse(text: Str) -> List<Rec> {
  let cs = text.chars();
  let n = cs.len();
  let mut recs: List<Rec> = [];
  let mut fields: List<Str> = [];
  let mut cur = "";
  let mut inq = false;
  let mut quoted = false;
  let mut after = false;
  let mut bad = false;
  let mut started = false;
  let mut i = 0;
  while i < n {
    let c = cs[i];
    if !inq && (c == "\n" || (c == "\r" && i + 1 < n && cs[i + 1] == "\n")) {
      if c == "\r" { i = i + 1; }
      if started {
        fields.push(cur);
        recs.push(Rec { fields: fields, bad: bad });
      }
      fields = [];
      cur = "";
      inq = false;
      quoted = false;
      after = false;
      bad = false;
      started = false;
      i = i + 1;
      continue;
    }
    started = true;
    if inq {
      if c == "\"" {
        if i + 1 < n && cs[i + 1] == "\"" {
          cur = cur + "\"";
          i = i + 1;
        } else {
          inq = false;
          after = true;
        }
      } else {
        cur = cur + c;
      }
    } else if c == "\"" {
      if cur.len() == 0 && !quoted && !after {
        inq = true;
        quoted = true;
      } else {
        bad = true;
      }
    } else if c == "," {
      fields.push(cur);
      cur = "";
      quoted = false;
      after = false;
    } else {
      if after { bad = true; }
      cur = cur + c;
    }
    i = i + 1;
  }
  if started {
    if inq { bad = true; }
    fields.push(cur);
    recs.push(Rec { fields: fields, bad: bad });
  }
  recs
}

fn all_digits(s: Str) -> Bool {
  if s.len() == 0 { return false; }
  for b in s.to_bytes() {
    if b < 48 || b > 57 { return false; }
  }
  true
}

fn parse_qty(s: Str) -> Option<Int> {
  let body = match s.strip_prefix("-") { Some(r) => r, None => s };
  if !all_digits(body) { return None; }
  s.parse_int()
}

fn parse_price(s: Str) -> Option<Price> {
  let parts = s.split(".");
  if parts.len() > 2 { return None; }
  let whole = parts[0];
  if !all_digits(whole) { return None; }
  let mut frac = "";
  if parts.len() == 2 {
    frac = parts[1];
    if !all_digits(frac) || frac.len() > 2 { return None; }
  }
  let mut padded = frac;
  if frac.len() == 0 { padded = "00"; } else if frac.len() == 1 { padded = frac + "0"; }
  let w = whole.parse_int()?;
  let f = padded.parse_int()?;
  Some(Price { cents: w * 100 + f, text: whole + "." + padded })
}

fn q(f: Str) -> Str {
  if f.contains(",") || f.contains("\"") || f.contains("\r") || f.contains("\n") {
    "\"" + f.replace("\"", "\"\"") + "\""
  } else {
    f
  }
}

fn money(c: Int) -> Str {
  let neg = c < 0;
  let a = if neg { 0 - c } else { c };
  let b = a % 100;
  let bs = if b < 10 { "0" + b.to_str() } else { b.to_str() };
  let s = (a / 100).to_str() + "." + bs;
  if neg { "-" + s } else { s }
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("sales.csv")?.to_str();
  let recs = parse(text);
  let mut clean = "region,product,qty,price,note\n";
  let mut agg: Map<Str, Agg> = Map::new();
  let mut badlist: List<Str> = [];
  let mut idx = 1;
  while idx < recs.len() {
    let r = recs[idx];
    let mut ok = !r.bad && r.fields.len() == 5;
    let mut qty = 0;
    let mut price = Price { cents: 0, text: "" };
    if ok {
      if r.fields[0].len() == 0 || r.fields[1].len() == 0 { ok = false; }
    }
    if ok {
      match parse_qty(r.fields[2]) {
        Some(v) => { qty = v; }
        None => { ok = false; }
      }
    }
    if ok {
      match parse_price(r.fields[3]) {
        Some(p) => { price = p; }
        None => { ok = false; }
      }
    }
    if !ok {
      badlist.push(idx.to_str());
    } else {
      clean = clean + q(r.fields[0]) + "," + q(r.fields[1]) + "," + q(r.fields[2]) + "," + price.text + "," + q(r.fields[4]) + "\n";
      let region = r.fields[0];
      let product = r.fields[1];
      let mut a = agg.get(region).unwrap_or(Agg { rev: 0, items: 0, prods: Map::new() });
      let line = qty * price.cents;
      a.rev = a.rev + line;
      a.items = a.items + qty;
      let mut p = a.prods;
      let old = p.get(product).unwrap_or(0);
      p.insert(product, old + line);
      a.prods = p;
      agg.insert(region, a);
    }
    idx = idx + 1;
  }
  out.write("clean.csv", clean.to_bytes())?;
  let mut res = "";
  for k in agg.keys() {
    let a = agg.get(k).unwrap_or(Agg { rev: 0, items: 0, prods: Map::new() });
    let mut best = "";
    let mut best_rev = 0;
    let mut first = true;
    for pk in a.prods.keys() {
      let v = a.prods.get(pk).unwrap_or(0);
      if first || v > best_rev {
        best = pk;
        best_rev = v;
        first = false;
      }
    }
    res = res + k + " revenue " + money(a.rev) + " items " + a.items.to_str() + " top " + best + "\n";
  }
  let total = if recs.len() > 0 { recs.len() - 1 } else { 0 };
  res = res + "records " + total.to_str() + " bad " + badlist.len().to_str();
  if badlist.len() > 0 {
    res = res + ": " + badlist.join(", ");
  }
  res = res + "\n";
  Ok(res)
}

fn tokenize(b: Bytes) -> List<Str> {
  let mut words: List<Str> = [];
  let mut cur: Bytes = "".to_bytes();
  for x in b {
    let alnum = (x >= 48 && x <= 57) || (x >= 65 && x <= 90) || (x >= 97 && x <= 122);
    let sep = x < 128 && !alnum;
    if sep {
      if cur.len() > 0 {
        words.push(cur.to_str().to_lowercase());
        cur = "".to_bytes();
      }
    } else {
      cur.push(x);
    }
  }
  if cur.len() > 0 {
    words.push(cur.to_str().to_lowercase());
  }
  words
}

fn uniq(words: List<Str>) -> List<Str> {
  let mut m: Map<Str, Bool> = Map::new();
  for w in words { m.insert(w, true); }
