}

fn walk(docs: Dir, dir: Str, out: List<Str>) -> Result<List<Str>, Str> {
  let mut res = out;
  let prefix = if dir == "" { "".to_str() } else { dir + "/" };
  let names = docs.list(dir).map_err(|e| "io error")?;
  for name in names {
    if name.ends_with("/") {
      let sub = prefix + name.slice(0, name.len() - 1);
      res = walk(docs, sub, res)?;
    } else {
      res.push(prefix + name);
    }
  }
  Ok(res)
}

fn drop_file(index: Kv, path: Str) -> Result<(), Str> {
  let old = index.get("d/" + path).map_err(|e| "kv error")?;
  if let Some(b) = old {
    for w in b.to_str().split("\n") {
      if w.len() > 0 {
        index.delete("w/" + w + "/" + path).map_err(|e| "kv error")?;
      }
    }
  }
  Ok(())
}

fn add_file(index: Kv, path: Str, content: Bytes, hash: Str) -> Result<(), Str> {
  let words = uniq(tokenize(content));
  for w in words {
    index.set("w/" + w + "/" + path, "".to_bytes()).map_err(|e| "kv error")?;
  }
  index.set("d/" + path, words.join("\n").to_bytes()).map_err(|e| "kv error")?;
  index.set("f/" + path, hash.to_bytes()).map_err(|e| "kv error")?;
  Ok(())
}

fn answer(index: Kv, line: Str, cur: Map<Str, Bool>) -> Result<Str, Str> {
  let words = uniq(tokenize(line.to_bytes()));
  let mut found: List<Str> = [];
  if words.len() == 0 {
    found = cur.keys();
  } else {
    let pre = "w/" + words[0] + "/";
    let keys = index.keys(pre).map_err(|e| "kv error")?;
    for k in keys {
      let p = k.slice(pre.len(), k.len());
      let mut ok = true;
      for w in words {
        let r = index.get("w/" + w + "/" + p).map_err(|e| "kv error")?;
        if r.is_none() { ok = false; break; }
      }
      if ok { found.push(p); }
    }
  }
  if found.len() == 0 {
    Ok(line + ": none\n")
  } else {
    Ok(line + ": " + found.join(", ") + "\n")
  }
}

fn main(docs: Dir, queries: Dir, index: Kv) -> Result<Str, Str> {
  let files = walk(docs, "", [])?;
  let mut cur: Map<Str, Bool> = Map::new();
  let mut status: Map<Str, Str> = Map::new();
  let mut unchanged = 0;
  for p in files {
    cur.insert(p, true);
    let content = docs.read(p).map_err(|e| "io error")?;
    let hash = content.sha256().to_hex();
    let old = index.get("f/" + p).map_err(|e| "kv error")?;
    if let Some(h) = old {
      if h.to_str() == hash {
        unchanged += 1;
      } else {
        drop_file(index, p)?;
        add_file(index, p, content, hash)?;
        status.insert(p, "changed");
      }
    } else {
      add_file(index, p, content, hash)?;
      status.insert(p, "added");
    }
  }
  let stored = index.keys("f/").map_err(|e| "kv error")?;
  for k in stored {
    let p = k.slice(2, k.len());
    if cur.get(p).is_none() {
      drop_file(index, p)?;
      index.delete("d/" + p).map_err(|e| "kv error")?;
      index.delete("f/" + p).map_err(|e| "kv error")?;
      status.insert(p, "removed");
    }
  }
  let mut out = "".to_str();
  for p in status.keys() {
    let s = status.get(p).unwrap_or("");
    out = out + s + " " + p + "\n";
  }
  out = out + "unchanged " + unchanged.to_str() + "\n";
  let text = queries.read("queries.txt").map_err(|e| "io error")?.to_str();
  for line in text.lines() {
    if line.trim().len() == 0 { continue; }
    out = out + answer(index, line, cur)?;
  }
  Ok(out)
}

