fn valid_utf8(b: Bytes) -> Bool {
  let n = b.len();
  let mut i = 0;
  while i < n {
    let c = b[i];
    if c < 128 {
      i += 1;
    } else if c >= 194 && c <= 223 {
      if i + 1 >= n { return false; }
      if b[i + 1] < 128 || b[i + 1] > 191 { return false; }
      i += 2;
    } else if c >= 224 && c <= 239 {
      if i + 2 >= n { return false; }
      let c1 = b[i + 1];
      let c2 = b[i + 2];
      if c1 < 128 || c1 > 191 || c2 < 128 || c2 > 191 { return false; }
      if c == 224 && c1 < 160 { return false; }
      if c == 237 && c1 >= 160 { return false; }
      i += 3;
    } else if c >= 240 && c <= 244 {
      if i + 3 >= n { return false; }
      let c1 = b[i + 1];
      let c2 = b[i + 2];
      let c3 = b[i + 3];
      if c1 < 128 || c1 > 191 || c2 < 128 || c2 > 191 || c3 < 128 || c3 > 191 { return false; }
      if c == 240 && c1 < 144 { return false; }
      if c == 244 && c1 >= 144 { return false; }
      i += 4;
    } else {
      return false;
    }
  }
  true
}

fn enc(s: Str) -> Str {
  let hex = "0123456789ABCDEF";
  let mut out = "";
  for b in s.to_bytes() {
    let ok = (b >= 48 && b <= 57) || (b >= 65 && b <= 90) || (b >= 97 && b <= 122) || b == 45 || b == 95 || b == 46 || b == 126;
    if ok {
      let mut o = "".to_bytes();
      o.push(b);
      out = out + o.to_str();
    } else {
      out = out + "%" + hex.slice(b / 16, b / 16 + 1) + hex.slice(b % 16, b % 16 + 1);
    }
  }
  out
}

fn parse_page(text: Str) -> Option<Page> {
  let Ok(doc) = text.parse_json() else { return None; };
  if doc.as_map().is_none() { return None; }
  let Some(changes) = doc.get("changes").and_then(|x| x.as_list()) else { return None; };
  match doc.get("next") {
    None => Some(Page { changes: changes, next: None }),
    Some(Json::Null) => Some(Page { changes: changes, next: None }),
    Some(Json::Str(s)) => Some(Page { changes: changes, next: Some(s) }),
    Some(Json::Num(n)) => Some(Page { changes: changes, next: Some(n.to_str()) }),
    _ => None,
  }
}

fn change_stmt(j: Json) -> Option<Stmt> {
  let Some(op) = j.get("op").and_then(|x| x.as_str()) else { return None; };
  let Some(sku) = j.get("sku").and_then(|x| x.as_str()) else { return None; };
  let Some(version) = j.get("version").and_then(|x| x.as_int()) else { return None; };
  if op == "upsert" {
    let Some(name) = j.get("name").and_then(|x| x.as_str()) else { return None; };
    let Some(qty) = j.get("qty").and_then(|x| x.as_int()) else { return None; };
    Some(Stmt {
      sql: "INSERT INTO items(sku, name, qty, version, deleted) VALUES(?, ?, ?, ?, 0) ON CONFLICT(sku) DO UPDATE SET name = excluded.name, qty = excluded.qty, version = excluded.version, deleted = 0 WHERE excluded.version > items.version",
      params: [SqlValue::Text(sku), SqlValue::Text(name), SqlValue::Int(qty), SqlValue::Int(version)],
    })
  } else if op == "delete" {
    Some(Stmt {
      sql: "INSERT INTO items(sku, name, qty, version, deleted) VALUES(?, '', 0, ?, 1) ON CONFLICT(sku) DO UPDATE SET name = '', qty = 0, version = excluded.version, deleted = 1 WHERE excluded.version > items.version",
      params: [SqlValue::Text(sku), SqlValue::Int(version)],
    })
  } else {
    None
  }
}

fn txt(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn int(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(n) => n,
    _ => 0,
  }
}

fn setup(db: Db) -> Result<Str, DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS items(sku TEXT PRIMARY KEY, name TEXT NOT NULL, qty INTEGER NOT NULL, version INTEGER NOT NULL, deleted INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY, v TEXT NOT NULL)", [])?;
  let rows = db.query("SELECT v FROM meta WHERE k = 'cursor'", [])?;
  if rows.len() == 0 { return Ok("0"); }
  Ok(txt(rows[0][0]))
}

fn report(db: Db) -> Result<Str, DbErr> {
  let rows = db.query("SELECT sku, qty, name FROM items WHERE deleted = 0 ORDER BY sku", [])?;
  let mut out = "";
  for row in rows {
    out = out + "\n" + txt(row[0]) + " " + int(row[1]).to_str() + " " + txt(row[2]);
  }
  Ok(out)
}

fn main(api: Http, db: Db) -> Result<Str, DbErr> {
  let mut cursor = setup(db)?;
  let mut pages = 0;
  let mut applied = 0;
  let mut stale = 0;
  let mut invalid = 0;
  let mut status = "complete";
  loop {
    let path = "/changes?cursor=" + enc(cursor);
    let r = api.send("GET", path, [], "".to_bytes());
    let Ok(resp) = r else {
      status = "stopped at " + cursor + " (no response)";
      break;
    };
    if resp.status != 200 {
      status = "stopped at " + cursor + " (status " + resp.status.to_str() + ")";
      break;
    }
    if !valid_utf8(resp.body) {
      status = "stopped at " + cursor + " (invalid page)";
      break;
    }
    let Some(page) = parse_page(resp.body.to_str()) else {
      status = "stopped at " + cursor + " (invalid page)";
      break;
    };
    let mut sqls: List<Str> = [];
    let mut params: List<List<SqlValue>> = [];
    let mut valid = 0;
    let mut inv = 0;
    for ch in page.changes {
      match change_stmt(ch) {
        Some(s) => {
          sqls.push(s.sql);
          params.push(s.params);
          valid += 1;
        }
        None => { inv += 1; }
      }
    }
    let new_cursor = page.next.unwrap_or(cursor);
    sqls.push("INSERT OR REPLACE INTO meta(k, v) VALUES('cursor', ?)");
    params.push([SqlValue::Text(new_cursor)]);
    let Ok(total) = db.transaction(sqls, params) else {
      status = "stopped at " + cursor + " (no response)";
      break;
    };
    let a = total - 1;
    applied += a;
    stale += valid - a;
    invalid += inv;
    pages += 1;
    if let Some(n) = page.next {
      cursor = n;
    } else {
      break;
    }
  }
  let head = "pages " + pages.to_str() + " applied " + applied.to_str() + " stale " + stale.to_str() + " invalid " + invalid.to_str();
  let items = report(db)?;
  Ok(head + "\n" + status + items)
}

struct Job { id: Str, state: Str, priority: Int, due: Int, attempts: Int }

fn enc(state: Str, p: Int, due: Int, a: Int) -> Bytes {
  (state + "|" + p.to_str() + "|" + due.to_str() + "|" + a.to_str()).to_bytes()
}

fn read_or_empty(d: Dir, name: Str) -> Str {
  match d.read(name) {
    Ok(b) => b.to_str(),
    Err(_) => "",
  }
}

fn scan_all(queue: Kv) -> Result<List<Job>, KvErr> {
  let mut jobs: List<Job> = [];
  let mut after: Option<Str> = None;
  loop {
    let page = queue.scan("job/", after, 1000)?;
    for e in page {
      let parts = e.value.to_str().split("|");
      if parts.len() == 4 {
        jobs.push(Job {
          id: e.key.slice(4, e.key.len()),
          state: parts[0],
          priority: parts[1].parse_int().unwrap_or(0),
          due: parts[2].parse_int().unwrap_or(0),
          attempts: parts[3].parse_int().unwrap_or(0),
        });
      }
    }
    if page.len() < 1000 { break; }
    after = Some(page[page.len() - 1].key);
  }
  Ok(jobs)
}

fn less(a: Job, b: Job) -> Bool {
  if a.priority != b.priority { return a.priority > b.priority; }
  if a.due != b.due { return a.due < b.due; }
  a.id < b.id
}

fn run(input: Dir, queue: Kv, now: Int) -> Result<Str, KvErr> {
  let mut out: List<Str> = [];

  // enqueue
  let lines = read_or_empty(input, "enqueue.jsonl").lines();
  for i in 0..lines.len() {
    let line = lines[i].trim();
    if line.len() == 0 { continue; }
    let n = (i + 1).to_str();
    let Ok(j) = line.parse_json() else { out.push("invalid line " + n); continue; };
    let Some(id) = j.get("id").and_then(|x| x.as_str()) else { out.push("invalid line " + n); continue; };
    let Some(p) = j.get("priority").and_then(|x| x.as_int()) else { out.push("invalid line " + n); continue; };
    let key = "job/" + id;
    let existing = queue.get(key)?;
    if existing.is_some() {
      out.push("duplicate ID");
      continue;
    }
    queue.set(key, enc("p", p, now, 0))?;
  }

  // work
  let script = match read_or_empty(input, "script.json").parse_json() {
    Ok(j) => j,
    Err(_) => Json::Null,
  };
  let all = scan_all(queue)?;
  let mut due = all.filter(|j| j.state == "p" && j.due <= now);
  due.sort_by(less);
  let cnt = if due.len() < 5 { due.len() } else { 5 };
  for i in 0..cnt {
    let job = due[i];
    let outcomes = script.get(job.id).and_then(|x| x.as_list()).unwrap_or([]);
    let mut ok = true;
    if outcomes.len() > 0 {
      let idx = if job.attempts < outcomes.len() { job.attempts } else { outcomes.len() - 1 };
      let o = outcomes[idx].as_str().unwrap_or("ok");
      if o == "fail" { ok = false; }
    }
    let n = job.attempts + 1;
    let key = "job/" + job.id;
    if ok {
      queue.set(key, enc("d", job.priority, job.due, n))?;
      out.push("done " + job.id);
    } else if n >= 4 {
      queue.set(key, enc("x", job.priority, job.due, n))?;
      out.push("dead " + job.id);
    } else {
      let secs = if n == 1 { 60 } else if n == 2 { 120 } else { 240 };
      queue.set(key, enc("p", job.priority, now + secs * 1000, n))?;
      out.push("retry " + job.id + " in " + secs.to_str());
    }
  }

  // summary
  let fin = scan_all(queue)?;
  let mut p = 0;
  let mut d = 0;
  let mut x = 0;
  for j in fin {
    if j.state == "p" { p += 1; }
    else if j.state == "d" { d += 1; }
    else if j.state == "x" { x += 1; }
  }
  out.push("pending " + p.to_str() + " done " + d.to_str() + " dead " + x.to_str());
  Ok(out.join("\n"))
}

fn main(input: Dir, queue: Kv, clock: Clock) -> Result<Str, KvErr> {
  let now = clock.now_ms();
  run(input, queue, now)
}

