struct Tok { kind: Int, s: Str }
struct Parsed { e: Expr, pos: Int }
struct Stmt { name: Str, is_let: Bool, e: Expr }

enum Expr {
  Num(Str),
  Var(Str),
  Neg(List<Expr>),
  Bin(Str, List<Expr>),
  Call(Str, List<Expr>),
}

fn maxv() -> Int { 9223372036854775807 }
fn minv() -> Int { -9223372036854775807 - 1 }

fn is_digit(c: Int) -> Bool { c >= 48 && c <= 57 }
fn is_alpha(c: Int) -> Bool { (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95 }
fn is_op_byte(c: Int) -> Bool {
  c == 43 || c == 45 || c == 42 || c == 47 || c == 37 || c == 94 || c == 40 || c == 41 || c == 44 || c == 61
}

fn tokenize(line: Str) -> Option<List<Tok>> {
  let b = line.to_bytes();
  let n = b.len();
  let mut toks: List<Tok> = [];
  let mut i = 0;
  while i < n {
    let c = b[i];
    if c == 32 {
      i += 1;
    } else if is_digit(c) {
      let mut j = i;
      loop {
        if j >= n { break; }
        if !is_digit(b[j]) { break; }
        j += 1;
      }
      toks.push(Tok { kind: 0, s: line.slice(i, j) });
      i = j;
    } else if is_alpha(c) {
      let mut j = i;
      loop {
        if j >= n { break; }
        if !(is_alpha(b[j]) || is_digit(b[j])) { break; }
        j += 1;
      }
      toks.push(Tok { kind: 1, s: line.slice(i, j) });
      i = j;
    } else if is_op_byte(c) {
      toks.push(Tok { kind: 2, s: line.slice(i, i + 1) });
      i += 1;
    } else {
      return None;
    }
  }
  Some(toks)
}

fn is_op(toks: List<Tok>, p: Int, s: Str) -> Bool {
  if p >= toks.len() { return false; }
  let t = toks[p];
  if t.kind != 2 { return false; }
  t.s == s
}

fn parse_expr(toks: List<Tok>, pos: Int) -> Option<Parsed> {
  let first = parse_term(toks, pos)?;
  let mut cur = first.e;
  let mut p = first.pos;
  loop {
    if is_op(toks, p, "+") || is_op(toks, p, "-") {
      let op = toks[p].s;
      let r = parse_term(toks, p + 1)?;
      cur = Expr::Bin(op, [cur, r.e]);
      p = r.pos;
    } else {
      break;
    }
  }
  Some(Parsed { e: cur, pos: p })
}

fn parse_term(toks: List<Tok>, pos: Int) -> Option<Parsed> {
  let first = parse_factor(toks, pos)?;
  let mut cur = first.e;
  let mut p = first.pos;
  loop {
    if is_op(toks, p, "*") || is_op(toks, p, "/") || is_op(toks, p, "%") {
      let op = toks[p].s;
      let r = parse_factor(toks, p + 1)?;
      cur = Expr::Bin(op, [cur, r.e]);
      p = r.pos;
    } else {
      break;
    }
  }
  Some(Parsed { e: cur, pos: p })
}

fn parse_factor(toks: List<Tok>, pos: Int) -> Option<Parsed> {
  if is_op(toks, pos, "-") {
    let r = parse_factor(toks, pos + 1)?;
    return Some(Parsed { e: Expr::Neg([r.e]), pos: r.pos });
  }
  parse_power(toks, pos)
}

fn parse_power(toks: List<Tok>, pos: Int) -> Option<Parsed> {
  let a = parse_atom(toks, pos)?;
  if is_op(toks, a.pos, "^") {
    let r = parse_factor(toks, a.pos + 1)?;
    return Some(Parsed { e: Expr::Bin("^", [a.e, r.e]), pos: r.pos });
  }
  Some(a)
}

fn parse_atom(toks: List<Tok>, p: Int) -> Option<Parsed> {
  if p >= toks.len() { return None; }
  let t = toks[p];
  if t.kind == 0 {
    return Some(Parsed { e: Expr::Num(t.s), pos: p + 1 });
  }
  if t.kind == 1 {
    if is_op(toks, p + 1, "(") {
      let first = parse_expr(toks, p + 2)?;
      let mut args: List<Expr> = [first.e];
      let mut q = first.pos;
      loop {
        if is_op(toks, q, ",") {
          let nx = parse_expr(toks, q + 1)?;
          args.push(nx.e);
          q = nx.pos;
        } else {
          break;
        }
      }
      if !is_op(toks, q, ")") { return None; }
      return Some(Parsed { e: Expr::Call(t.s, args), pos: q + 1 });
    }
    return Some(Parsed { e: Expr::Var(t.s), pos: p + 1 });
  }
  if is_op(toks, p, "(") {
    let r = parse_expr(toks, p + 1)?;
    if !is_op(toks, r.pos, ")") { return None; }
    return Some(Parsed { e: r.e, pos: r.pos + 1 });
  }
  None
}

fn parse_line(line: Str) -> Option<Stmt> {
  let toks = tokenize(line)?;
  if toks.len() == 0 { return None; }
  let t0 = toks[0];
  if t0.kind == 1 && t0.s == "let" {
    if toks.len() < 4 { return None; }
    if toks[1].kind != 1 { return None; }
    if !is_op(toks, 2, "=") { return None; }
    let r = parse_expr(toks, 3)?;
    if r.pos != toks.len() { return None; }
    return Some(Stmt { name: toks[1].s, is_let: true, e: r.e });
  }
  let r = parse_expr(toks, 0)?;
  if r.pos != toks.len() { return None; }
  Some(Stmt { name: "", is_let: false, e: r.e })
}

fn add(a: Int, b: Int) -> Result<Int, Str> {
  if b > 0 {
    if a > maxv() - b { return Err("overflow"); }
  } else if b < 0 {
    if a < minv() - b { return Err("overflow"); }
  }
  Ok(a + b)
}

fn sub(a: Int, b: Int) -> Result<Int, Str> {
  if b < 0 {
    if a > maxv() + b { return Err("overflow"); }
  } else if b > 0 {
    if a < minv() + b { return Err("overflow"); }
  }
  Ok(a - b)
}

fn mul(a: Int, b: Int) -> Result<Int, Str> {
  if a == 0 || b == 0 { return Ok(0); }
  if a > 0 {
    if b > 0 {
      if a > maxv() / b { return Err("overflow"); }
    } else {
      if b < minv() / a { return Err("overflow"); }
    }
  } else {
    if b > 0 {
      if a < minv() / b { return Err("overflow"); }
    } else {
      if a < maxv() / b { return Err("overflow"); }
    }
  }
  Ok(a * b)
}

fn pow(a: Int, b: Int) -> Result<Int, Str> {
  if b < 0 { return Err("negative exponent"); }
  if b == 0 { return Ok(1); }
  if a == 0 { return Ok(0); }
  if a == 1 { return Ok(1); }
  if a == -1 {
    if b % 2 == 0 { return Ok(1); }
    return Ok(-1);
  }
  if b > 64 { return Err("overflow"); }
  let mut r = 1;
  let mut i = 0;
  while i < b {
    r = mul(r, a)?;
    i += 1;
  }
  Ok(r)
}

fn apply(op: Str, a: Int, b: Int) -> Result<Int, Str> {
  match op {
    "+" => add(a, b),
    "-" => sub(a, b),
    "*" => mul(a, b),
    "/" => {
      if b == 0 { return Err("division by zero"); }
      if b == -1 { return sub(0, a); }
      Ok(a / b)
    },
    "%" => {
      if b == 0 { return Err("division by zero"); }
      if b == -1 { return Ok(0); }
      Ok(a % b)
    },
    _ => pow(a, b),
  }
}

fn arity(name: Str) -> Int {
  if name == "min" || name == "max" { return 2; }
  if name == "abs" { return 1; }
  -1
}

fn eval(e: Expr, env: Map<Str, Int>) -> Result<Int, Str> {
  match e {
    Expr::Num(s) => match s.parse_int() {
      Some(v) => Ok(v),
      None => Err("overflow"),
    },
    Expr::Var(name) => match env.get(name) {
      Some(v) => Ok(v),
      None => Err("unknown variable " + name),
    },
    Expr::Neg(kids) => {
      let a = eval(kids[0], env)?;
      sub(0, a)
    },
    Expr::Bin(op, kids) => {
      let a = eval(kids[0], env)?;
      let b = eval(kids[1], env)?;
      apply(op, a, b)
    },
    Expr::Call(name, args) => {
      let want = arity(name);
      if want < 0 { return Err("unknown function " + name); }
      if args.len() != want { return Err("wrong number of arguments to " + name); }
      let mut vals: List<Int> = [];
      for a in args {
        let v = eval(a, env)?;
        vals.push(v);
      }
      if name == "abs" {
        if vals[0] < 0 { return sub(0, vals[0]); }
        return Ok(vals[0]);
      }
      if name == "min" { return Ok(vals[0].min(vals[1])); }
      Ok(vals[0].max(vals[1]))
    },
  }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("program.txt")?.to_str();
  let mut env: Map<Str, Int> = Map::new();
  let mut out: List<Str> = [];
  let mut n = 0;
  for line in text.lines() {
    n += 1;
    if line.trim() == "" { continue; }
    let prefix = n.to_str() + ": ";
    match parse_line(line) {
      None => { out.push(prefix + "error: syntax error"); },
      Some(st) => {
        match eval(st.e, env) {
          Err(m) => { out.push(prefix + "error: " + m); },
          Ok(v) => {
            if st.is_let {
              env.insert(st.name, v);
              out.push(prefix + st.name + " = " + v.to_str());
            } else {
              out.push(prefix + v.to_str());
            }
          },
        }
      },
    }
  }
  Ok(out.join("\n"))
}

struct Sub { state: Str, seq: Int }
struct Outcome { status: Int, body: Str }

fn reply(res: Outgoing, status: Int, body: Str) -> Str {
  match res.send(status, ["content-type"], ["application/json"], body.to_bytes()) {
    Ok(_) => "",
    Err(_) => "send failed",
  }
}

fn err_body(msg: Str) -> Str {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Json::Obj(m).to_json()
}

fn status_body(s: Str) -> Str {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("status", Json::Str(s));
  Json::Obj(m).to_json()
}

fn note(log: Log, s: Str) {
  match log.write(s) {
    Ok(_) => {},
    Err(_) => {},
  }
}

fn text_at(row: List<SqlValue>, i: Int) -> Str {
  match row[i] {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn int_at(row: List<SqlValue>, i: Int) -> Int {
  match row[i] {
    SqlValue::Int(n) => n,
    _ => 0,
  }
}

fn ensure_schema(db: Db) -> Result<(), DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, sub TEXT NOT NULL, seq INTEGER NOT NULL, type TEXT NOT NULL, applied INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS subs (id TEXT PRIMARY KEY, state TEXT NOT NULL, seq INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS hist (sub TEXT NOT NULL, seq INTEGER NOT NULL, state TEXT NOT NULL, PRIMARY KEY (sub, seq))", [])?;
  Ok(())
}

fn load_sub(db: Db, id: Str) -> Result<Option<Sub>, DbErr> {
  let rows = db.query("SELECT state, seq FROM subs WHERE id = ?", [SqlValue::Text(id)])?;
  if rows.len() == 0 { return Ok(None); }
  Ok(Some(Sub { state: text_at(rows[0], 0), seq: int_at(rows[0], 1) }))
}

fn transition(from: Str, ty: Str) -> Option<Str> {
  if ty == "subscription.created" {
    if from == "none" { return Some("created"); }
    return None;
  }
  if ty == "subscription.activated" {
    if from == "created" || from == "past_due" { return Some("active"); }
    return None;
  }
  if ty == "payment.failed" {
    if from == "active" { return Some("past_due"); }
    return None;
  }
  if ty == "subscription.canceled" {
    if from == "created" || from == "active" || from == "past_due" { return Some("canceled"); }
    return None;
  }
  None
}

fn drain(db: Db, log: Log, sub: Str) -> Result<Int, DbErr> {
  let mut k = 0;
  loop {
    let cur = load_sub(db, sub)?;
    let mut state = "none";
    let mut last = 0;
    if let Some(s) = cur {
      state = s.state;
      last = s.seq;
    }
    let rows = db.query("SELECT id, type FROM events WHERE sub = ? AND seq = ? AND applied = 0 ORDER BY rowid LIMIT 1", [SqlValue::Text(sub), SqlValue::Int(last + 1)])?;
    if rows.len() == 0 { break; }
    let eid = text_at(rows[0], 0);
    let ty = text_at(rows[0], 1);
    let next = transition(state, ty);
    let mut new_state = state;
    let mut stmts: List<Str> = [];
    let mut params: List<List<SqlValue>> = [];
    stmts.push("UPDATE events SET applied = 1 WHERE id = ?");
    params.push([SqlValue::Text(eid)]);
    if let Some(n) = next {
      new_state = n;
    } else {
      note(log, "invalid transition " + eid);
    }
    stmts.push("INSERT INTO subs (id, state, seq) VALUES (?, ?, ?) ON CONFLICT(id) DO UPDATE SET state = excluded.state, seq = excluded.seq");
    params.push([SqlValue::Text(sub), SqlValue::Text(new_state), SqlValue::Int(last + 1)]);
    if next.is_some() {
      stmts.push("INSERT INTO hist (sub, seq, state) VALUES (?, ?, ?)");
      params.push([SqlValue::Text(sub), SqlValue::Int(last + 1), SqlValue::Text(new_state)]);
    }
    db.transaction(stmts, params)?;
    k += 1;
  }
  Ok(k)
}

fn process(db: Db, log: Log, id: Str, ty: Str, sub: Str, seq: Int) -> Result<Outcome, DbErr> {
  ensure_schema(db)?;
  let cur = load_sub(db, sub)?;
  let mut last = 0;
  if let Some(s) = cur { last = s.seq; }
  let flag = if seq <= last { 2 } else { 0 };
  let n = db.exec("INSERT OR IGNORE INTO events (id, sub, seq, type, applied) VALUES (?, ?, ?, ?, ?)", [SqlValue::Text(id), SqlValue::Text(sub), SqlValue::Int(seq), SqlValue::Text(ty), SqlValue::Int(flag)])?;
  if n == 0 {
    return Ok(Outcome { status: 200, body: status_body("duplicate") });
  }
  if flag == 2 {
    return Ok(Outcome { status: 200, body: status_body("stale") });
  }
  if seq > last + 1 {
    return Ok(Outcome { status: 202, body: status_body("queued") });
  }
  let k = drain(db, log, sub)?;
  let mut m: Map<Str, Json> = Map::new();
  m.insert("status", Json::Str("applied"));
  m.insert("applied", Json::Num(k));
  Ok(Outcome { status: 200, body: Json::Obj(m).to_json() })
}

fn post(req: Incoming, res: Outgoing, db: Db, secrets: Dir, log: Log) -> Str {
  let key0 = match secrets.read("webhook.key") {
    Ok(b) => b,
    Err(_) => return reply(res, 500, err_body("server error")),
  };
  let mut key = key0;
  if key.len() > 0 && key[key.len() - 1] == 10 {
    key = key.slice(0, key.len() - 1);
  }
  let body = req.body();
  let mut msg = key;
  msg.extend(".".to_bytes());
  msg.extend(body);
  let expected = msg.sha256().to_hex();
  let names = req.header_names();
  let values = req.header_values();
  let mut sig: Option<Str> = None;
  for i in 0..names.len() {
    if sig.is_none() && names[i] == "x-signature" {
      sig = Some(values[i].trim());
    }
  }
  let ok = match sig {
    Some(v) => match v.strip_prefix("sha256=") {
      Some(h) => expected.ct_eq(h),
      None => false,
    },
    None => false,
  };
  if !ok {
    note(log, "rejected signature");
    return reply(res, 401, err_body("bad signature"));
  }
  let doc = match body.to_str().parse_json() {
    Ok(j) => j,
    Err(_) => return reply(res, 400, err_body("invalid event")),
  };
  if doc.as_map().is_none() {
    return reply(res, 400, err_body("invalid event"));
  }
  let Some(id) = doc.get("id").and_then(|j| j.as_str()) else {
    return reply(res, 400, err_body("invalid event"));
  };
  let Some(ty) = doc.get("type").and_then(|j| j.as_str()) else {
    return reply(res, 400, err_body("invalid event"));
  };
  let Some(sub) = doc.get("subscription").and_then(|j| j.as_str()) else {
    return reply(res, 400, err_body("invalid event"));
  };
  let Some(seq) = doc.get("seq").and_then(|j| j.as_int()) else {
    return reply(res, 400, err_body("invalid event"));
  };
  if seq < 1 {
    return reply(res, 400, err_body("invalid event"));
  }
  if ty != "subscription.created" && ty != "subscription.activated" && ty != "payment.failed" && ty != "subscription.canceled" {
    return reply(res, 400, err_body("invalid event"));
  }
  match process(db, log, id, ty, sub, seq) {
    Ok(o) => reply(res, o.status, o.body),
    Err(_) => reply(res, 500, err_body("server error")),
  }
}

fn get_sub(res: Outgoing, db: Db, id: Str) -> Str {
  match ensure_schema(db) {
    Ok(_) => {},
    Err(_) => return reply(res, 500, err_body("server error")),
  }
  let cur = match load_sub(db, id) {
    Ok(c) => c,
    Err(_) => return reply(res, 500, err_body("server error")),
  };
  let Some(s) = cur else {
    return reply(res, 404, err_body("not found"));
  };
  let rows = match db.query("SELECT state FROM hist WHERE sub = ? ORDER BY seq", [SqlValue::Text(id)]) {
    Ok(r) => r,
    Err(_) => return reply(res, 500, err_body("server error")),
  };
  let mut hist: List<Json> = [];
  for r in rows {
    hist.push(Json::Str(text_at(r, 0)));
  }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Str(id));
  m.insert("state", Json::Str(s.state));
  m.insert("seq", Json::Num(s.seq));
  m.insert("history", Json::Arr(hist));
  reply(res, 200, Json::Obj(m).to_json())
}

fn main(req: Incoming, res: Outgoing, db: Db, secrets: Dir, log: Log) -> Str {
  let method = req.method();
  let path = req.target().split("?")[0];
  if method == "POST" && path == "/webhooks" {
    return post(req, res, db, secrets, log);
  }
  if method == "GET" {
    if let Some(id) = path.strip_prefix("/subscriptions/") {
      if id.len() > 0 {
        return get_sub(res, db, id);
      }
    }
  }
  reply(res, 404, err_body("not found"))
}
